class FakeModelHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def log_message(self, *args):
        pass

    def _send(self, payload, content_type="application/json", status=200):
        body = payload if isinstance(payload, bytes) else json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if "balance" in self.path:
            self._send({"is_available": True, "balance_infos": [{"currency": "USD", "total_balance": "9.99"}]})
            return
        if self.path.startswith("/searchlocal"):
            port = self.server.server_address[1]
            self._send({"results": [
                {"title": "本地结果一", "url": "http://127.0.0.1:%d/page1" % port,
                 "content": "摘要一"},
                {"title": "本地结果二", "url": "http://127.0.0.1:%d/page2" % port,
                 "content": "摘要二"},
                {"title": "本地结果三", "url": "http://127.0.0.1:%d/page3" % port,
                 "content": "摘要三"},
            ]})
            return
        if self.path.startswith("/searchhtml"):
            self._send(("<html><body><a href='http://example.com/a'>HTML 结果一</a>"
                        "<a href='http://example.com/b'>HTML 结果二</a></body></html>").encode("utf-8"),
                       "text/html")
            return
        if self.path.startswith("/search"):
            query = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get("q", [""])[0]
            self._send({"results": [
                {"title": "结果一 " + query, "url": "http://example.com/1", "content": "摘要一"},
                {"title": "结果二", "link": "http://example.com/2", "description": "摘要二"},
            ]})
            return
        if self.path.startswith("/page"):
            self._send(("<html><head><title>页面</title><style>p{color:red}</style></head>"
                        "<body><h1>标题</h1><p>正文内容 %s</p><script>var a=1;</script></body></html>"
                        % self.path).encode("utf-8"), "text/html")
            return
        # "测试连接"打的是 GET /models：这里可以模拟网关返回 401/404
        status = getattr(self.server, "get_status", 200)
        if status != 200:
            self._send({"error": {"message": "Authentication Fails", "type": "authentication_error"}},
                       status=status)
            return
        self._send({"object": "list", "data": [{"id": "fake-model"}, {"id": "fake-reasoner"}]})
    def do_POST(self):
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length else b"{}"
        request = json.loads(raw.decode("utf-8"))
        self.server.paths.append(self.path)
        if self.path in getattr(self.server, "missing_paths", ()):  # 模拟地址写错导致的 404
            self._send({"error": {"message": "not found: " + self.path}}, status=404)
            return
        self.server.requests.append(request)
        index = len(self.server.requests) - 1
        script = self.server.script
        step = script[index] if index < len(script) else script[-1]
        chunks = step(request) if callable(step) else step
        if isinstance(chunks, dict):
            body = json.dumps(chunks.get("error") or {}).encode("utf-8")
            self.send_response(chunks.get("__status__", 400))
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.end_headers()
        for chunk in chunks:
            self.wfile.write(("data: " + json.dumps(chunk, ensure_ascii=False) + "\n\n").encode("utf-8"))
            self.wfile.flush()
            time.sleep(getattr(self.server, "chunk_delay", 0.005))
        self.wfile.write(b"data: [DONE]\n\n")
        self.wfile.flush()


class FakeModelServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        """客户端中途断开（取消运行、断网测试）是正常情况，别刷一屏回溯。"""
        exc = sys.exc_info()[1]
        if isinstance(exc, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError,
                            TimeoutError, socket.timeout)):
            return
        if isinstance(exc, OSError) and getattr(exc, "winerror", None) in (10053, 10054, 10038):
            return
        ThreadingHTTPServer.handle_error(self, request, client_address)


def usage(prompt=100, completion=12, hit=80, miss=20, reasoning=5):
    return {
        "prompt_tokens": prompt,
        "completion_tokens": completion,
        "total_tokens": prompt + completion,
        "prompt_cache_hit_tokens": hit,
        "prompt_cache_miss_tokens": miss,
        "prompt_tokens_details": {"cached_tokens": hit},
        "completion_tokens_details": {"reasoning_tokens": reasoning},
    }


def tool_round(name, arguments, call_id="call_1"):
    """构造一轮“思考 + 工具调用”的流式响应。"""
    pieces = [arguments[i:i + 8] for i in range(0, len(arguments), 8)] or [""]
    chunks = [
        {"choices": [{"delta": {"role": "assistant", "reasoning_content": "我先读取文件。", "content": ""}}]},
        {"choices": [{"delta": {"tool_calls": [
            {"index": 0, "id": call_id, "type": "function", "function": {"name": name, "arguments": ""}}]}}]},
    ]
    for piece in pieces:
        chunks.append({"choices": [{"delta": {"tool_calls": [
            {"index": 0, "function": {"arguments": piece}}]}}]})
    chunks.append({"choices": [{"delta": {}, "finish_reason": "tool_calls"}], "usage": usage()})
    return chunks


def answer_round(text):
    return [
        {"choices": [{"delta": {"content": text}}]},
        {"choices": [{"delta": {}, "finish_reason": "stop"}], "usage": usage()},
    ]


def reasoning_round(thought, answer="好的。"):
    """一轮带原生 reasoning_content 的流式响应（逐块吐出，模拟真实增量）。"""
    chunks = []
    for index in range(0, len(thought), 6):
        chunks.append({"choices": [{"delta": {"reasoning_content": thought[index:index + 6]}}]})
    chunks.append({"choices": [{"delta": {"content": answer}}]})
    chunks.append({"choices": [{"delta": {}, "finish_reason": "stop"}], "usage": usage()})
    return chunks


def length_round(text):
    """被 max_tokens 截断的一轮（finish_reason=length）。"""
    return [
        {"choices": [{"delta": {"content": text}}]},
        {"choices": [{"delta": {}, "finish_reason": "length"}], "usage": usage()},
    ]


def tiny_png(width=8, height=8):
    """生成一张真实的 PNG（用于识图相关测试，不依赖任何图片库）。"""
    import struct
    import zlib

    def chunk(tag, data):
        return (struct.pack(">I", len(data)) + tag + data +
                struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF))

    raw = b"".join(b"\x00" + b"\x20\x80\xe0" * width for _ in range(height))
    return (b"\x89PNG\r\n\x1a\n" +
            chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)) +
            chunk(b"IDAT", zlib.compress(raw)) +
            chunk(b"IEND", b""))


def _test_timeout(default=30):
    """HTTP 超时（秒）。慢机器上可以用 W7A_TEST_TIMEOUT 放大。

    真 Win7 客机（单核、还在同时跑别的用例）比宿主慢两倍多：SSE 两条事件之间
    偶尔会隔三十秒以上，于是 30 秒的默认超时把"子代理还没跑完"误判成失败。
    这个环境变量**只是让它多等一会儿**，不改任何断言。
    """
    try:
        return float(os.environ.get("W7A_TEST_TIMEOUT") or default)
    except (TypeError, ValueError):
        return default


def sse_chat(port, payload, on_event=None, timeout=None):
    """向 /api/chat 发起请求并把 SSE 事件收集成列表。"""
    request = urllib.request.Request(
        "http://127.0.0.1:%d/api/chat" % port,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"})
    events = []
    with urllib.request.urlopen(request, timeout=timeout or _test_timeout()) as response:
        for raw in response:
            line = raw.decode("utf-8", "replace").strip()
            if not line.startswith("data:"):
                continue
            event = json.loads(line[5:].strip())
            events.append(event)
            if on_event is not None:
                on_event(event)
    return events


def post_json(port, path, payload):
    request = urllib.request.Request(
        "http://127.0.0.1:%d%s" % (port, path),
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(request, timeout=_test_timeout()) as response:
        return json.loads(response.read().decode("utf-8"))


def get_json(port, path):
    with urllib.request.urlopen("http://127.0.0.1:%d%s" % (port, path),
                                timeout=_test_timeout()) as response:
        return json.loads(response.read().decode("utf-8"))


def get_text(port, path):
    """悬浮工具栏那几个接口返回的是纯文本（PowerShell 2.0 没有 JSON 解析）。"""
    with urllib.request.urlopen("http://127.0.0.1:%d%s" % (port, path), timeout=30) as response:
        return response.read().decode("utf-8")


def post_text(port, path, payload):
    request = urllib.request.Request(
        "http://127.0.0.1:%d%s" % (port, path),
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(request, timeout=60) as response:
        return response.read().decode("utf-8")


