class WebUITestCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix="w7a-test-")
        self.base = os.path.join(self.tmp, "agent")
        self.workspace = os.path.join(self.tmp, "work")
        self.data = os.path.join(self.tmp, "data")
        os.makedirs(os.path.join(self.base, "config"))
        os.makedirs(self.workspace)
        os.makedirs(self.data)
        self.upstream = FakeModelServer(("127.0.0.1", 0), FakeModelHandler)
        self.upstream.requests = []
        self.upstream.paths = []
        self.upstream.missing_paths = ()
        self.upstream.script = [answer_round("好的。")]
        threading.Thread(target=self.upstream.serve_forever, daemon=True).start()
        self.upstream_port = self.upstream.server_address[1]
        self.write_agent_config()
        self.write_webui_config()
        self.http = None

    def tearDown(self):
        if self.http is not None:
            self.http.shutdown()
            self.http.server_close()
        self.upstream.shutdown()
        self.upstream.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def write_agent_config(self, extra=None):
        config = {
            "base_url": "http://127.0.0.1:%d" % self.upstream_port,
            "model": "fake-model",
            "api_key": "sk-test-0000000000",
            "stream": True,
            "timeout_seconds": 30,
            "command": {
                "enabled": True,
                "confirm_prefixes": ["del", "powershell", "net"],
                "blocked_prefixes": ["format"],
                "always_confirm": False,
                "audit_log": os.path.join("logs", "commands.log"),
                "max_output_bytes": 65536,
                "max_tool_rounds": 4,
            },
            "max_content_chars": 100000,
        }
        config.update(extra or {})
        with open(os.path.join(self.base, "config", "agent.json"), "w", encoding="utf-8") as handle:
            json.dump(config, handle, ensure_ascii=False)

    def write_webui_config(self, extra=None):
        webui = {
            "host": "127.0.0.1",
            "port": 0,
            "open_browser": False,
            "workspace_root": self.workspace,
            "data_dir": self.data,
            "tools_enabled": True,
            "max_tool_rounds": 4,
            "temperature": 0.3,
            # 熔断在**产品里默认是关的**（设置里那一项，老师不勾就永远不判"你在打转"）。
            # 自检里要验的正是熔断本身的行为，所以基准配置显式打开；
            # 想验"关着时确实不管"，单独写用例把这一项设成 False。
            "loop_breaker": True,
            "loop_repeat_limit": 3,
            "price": {"currency": "USD", "unit": 1000000,
                      "cache_hit": 0.028, "cache_miss": 0.28, "output": 0.42},
        }
        webui.update(extra or {})
        with open(os.path.join(self.base, "config", "webui.json"), "w", encoding="utf-8") as handle:
            json.dump(webui, handle, ensure_ascii=False)

    def start_http(self, port=0):
        self.http = server_module.build_server(self.base, "127.0.0.1", port, data_dir=self.data)
        threading.Thread(target=self.http.serve_forever, daemon=True).start()
        return self.http.server_address[1]

    def settings(self):
        return core.Settings(self.base)

    def make_tools(self):
        return tools_module.Tools(self.settings(), self.data)


