class TestBasics(WebUITestCase):
    def test_normalize_endpoint(self):
        cases = {
            "https://api.deepseek.com": "https://api.deepseek.com/chat/completions",
            "https://api.deepseek.com/": "https://api.deepseek.com/chat/completions",
            "https://api.deepseek.com/v1": "https://api.deepseek.com/v1/chat/completions",
            "https://api.deepseek.com/v1/chat/completions": "https://api.deepseek.com/v1/chat/completions",
            "http://10.0.0.5:8000/beta": "http://10.0.0.5:8000/beta/chat/completions",
            "": "",
        }
        for raw, expected in cases.items():
            self.assertEqual(core.normalize_endpoint(raw), expected, raw)

    def test_endpoint_candidates(self):
        # 裸域名：先试 /chat/completions，再退到 /v1/chat/completions
        self.assertEqual(core.endpoint_candidates("https://api.deepseek.com"),
                         ["https://api.deepseek.com/chat/completions",
                          "https://api.deepseek.com/v1/chat/completions"])
        # 已经带 /v1 或完整路径时不再追加，避免出现 /v1/v1/chat/completions
        self.assertEqual(core.endpoint_candidates("https://api.deepseek.com/v1"),
                         ["https://api.deepseek.com/v1/chat/completions"])
        self.assertEqual(core.endpoint_candidates("https://api.deepseek.com/v1/chat/completions"),
                         ["https://api.deepseek.com/v1/chat/completions"])
        self.assertEqual(core.endpoint_candidates(""), [])

    def test_mask_secret(self):
        self.assertEqual(core.mask_secret(""), "")
        self.assertEqual(core.mask_secret("short"), "****")
        self.assertEqual(core.mask_secret("sk-1234567890abcd"), "sk-1****abcd")

    def test_settings_and_profile_override(self):
        self.write_agent_config({
            "active_model": "fast",
            "models": {"fast": {"model": "fake-reasoner", "base_url": "http://127.0.0.1:%d/v1" % self.upstream_port}},
        })
        settings = core.Settings(self.base)
        resolved = settings.resolve_model()
        self.assertEqual(resolved["model"], "fake-reasoner")
        self.assertTrue(resolved["endpoint"].endswith("/v1/chat/completions"))
        public = settings.public_config()
        self.assertNotIn("sk-test", json.dumps(public))
        self.assertTrue(public["hasApiKey"])
        # 界面显示原始写法，实际请求用规范化地址
        self.assertEqual(public["baseUrlRaw"], self.settings().agent["base_url"])
        self.assertTrue(public["endpoint"].endswith("/chat/completions"))
        self.assertTrue(public["allowOutsideWorkspace"])

    def test_trim_messages_keeps_tool_pairing(self):
        messages = [
            {"role": "user", "content": "q1"},
            {"role": "assistant", "content": "", "tool_calls": [{"id": "a"}]},
            {"role": "tool", "tool_call_id": "a", "content": "r"},
            {"role": "assistant", "content": "a1"},
            {"role": "user", "content": "q2"},
            {"role": "assistant", "content": "a2"},
        ]
        trimmed = core.trim_messages(messages, 3)
        self.assertEqual(trimmed[0]["role"], "user")
        for index, message in enumerate(trimmed):
            if message["role"] == "tool":
                self.assertTrue(any(row["role"] == "assistant" and row.get("tool_calls")
                                    for row in trimmed[:index]))

    def test_usage_and_cost(self):
        normalized = core.normalize_usage(usage(prompt=1000, completion=100, hit=800, miss=200, reasoning=40))
        self.assertEqual(normalized["cache_hit_tokens"], 800)
        self.assertEqual(normalized["reasoning_tokens"], 40)
        price = {"unit": 1000000, "cache_hit": 0.028, "cache_miss": 0.28, "output": 0.42}
        cost = core.estimate_cost({"cache_hit_tokens": 1000000, "cache_miss_tokens": 0,
                                   "completion_tokens": 0}, price)
        self.assertAlmostEqual(cost["cost"], 0.028, places=6)
        both = core.estimate_cost({"cache_hit_tokens": 1000000, "cache_miss_tokens": 1000000,
                                   "completion_tokens": 1000000}, price)
        self.assertAlmostEqual(both["cost"], 0.028 + 0.28 + 0.42, places=6)

    def test_to_api_messages_strips_reasoning(self):
        messages = [
            {"role": "user", "content": "你好"},
            {"role": "assistant", "content": "在", "reasoning": "想了很久",
             "tool_calls": [{"id": "c1", "type": "function",
                             "function": {"name": "read_file", "arguments": "{}"}}]},
            {"role": "tool", "tool_call_id": "c1", "content": "内容", "status": "ok"},
        ]
        payload = core.to_api_messages("系统提示", messages)
        self.assertEqual(payload[0], {"role": "system", "content": "系统提示"})
        self.assertNotIn("reasoning", payload[2])
        self.assertEqual(payload[2]["tool_calls"][0]["id"], "c1")
        self.assertEqual(payload[3]["tool_call_id"], "c1")
        self.assertEqual(set(payload[3].keys()), {"role", "tool_call_id", "content"})


class TestImages(WebUITestCase):
    """识图：图片尺寸解析、多模态消息构造、历史图片裁剪、拒绝识别提示。"""

    def make_image(self, name="图.png", width=8, height=8):
        path = os.path.join(self.workspace, name)
        with open(path, "wb") as handle:
            handle.write(tiny_png(width, height))
        return path

    def test_image_size_and_mime(self):
        data = tiny_png(64, 32)
        self.assertEqual(core.image_size(data), (64, 32))
        path = self.make_image("尺寸.png", 20, 12)
        self.assertEqual(core.image_mime(path), "image/png")
        self.assertTrue(core.is_image_path(path))
        self.assertFalse(core.is_image_path(os.path.join(self.workspace, "a.txt")))
        with open(path, "rb") as handle:
            self.assertEqual(core.image_size(handle.read()), (20, 12))

    def test_to_api_messages_builds_image_parts(self):
        path = self.make_image()
        messages = [
            {"role": "user", "content": "这张图里是什么？", "images": [{"path": path, "name": "图.png"}]},
        ]
        payload = core.to_api_messages("系统", messages)
        content = payload[1]["content"]
        self.assertIsInstance(content, list)
        self.assertEqual(content[0]["type"], "text")
        self.assertEqual(content[1]["type"], "image_url")
        self.assertTrue(content[1]["image_url"]["url"].startswith("data:image/png;base64,"))

    def test_to_api_messages_skips_unreadable_image(self):
        missing = os.path.join(self.workspace, "不存在.png")
        payload = core.to_api_messages("系统", [
            {"role": "user", "content": "看图", "images": [{"path": missing, "name": "不存在.png"}]}])
        content = payload[1]["content"]
        self.assertIsInstance(content, list)
        self.assertEqual(len(content), 1)
        self.assertIn("未能附加", content[0]["text"])

    def test_image_history_trim_keeps_only_recent(self):
        paths = [self.make_image("图%d.png" % index) for index in range(3)]
        messages = [{"role": "user", "content": "第 %d 张" % (index + 1),
                     "images": [{"path": path}]}
                    for index, path in enumerate(paths)]
        payload = core.to_api_messages("系统", messages)
        self.assertIsInstance(payload[1]["content"], str)          # 最早的一张被省略
        self.assertIn("此前的图片已省略", payload[1]["content"])
        for index in (2, 3):
            self.assertIsInstance(payload[index]["content"], list)
            self.assertEqual(payload[index]["content"][1]["type"], "image_url")

    def test_looks_like_image_refusal(self):
        self.assertTrue(core.looks_like_image_refusal("抱歉，我无法查看这张图片，因为图片未能成功加载。"))
        self.assertFalse(core.looks_like_image_refusal("这张图是一张数学课件的截图，标题是分数的意义。"))


