class TestCommandPolicy(WebUITestCase):
    def setUp(self):
        WebUITestCase.setUp(self)
        self.handler = self.make_tools()

    def authorize(self, command):
        return self.handler.authorize("run_command", {"command": command})

    def test_blocked_prefix(self):
        verdict = self.authorize("format c: /q")
        self.assertFalse(verdict["allow"])
        self.assertEqual(verdict["status"], "denied")

    def test_high_risk_runs_without_confirm_by_default(self):
        """默认不逐条确认：老师要的是"说一句就干完"，del/powershell 都直接跑。"""
        self.assertFalse(core.WEBUI_DEFAULTS["confirm_high_risk_commands"])
        for command in ("powershell -Command dir", "del 旧文件.txt", "cmd /c powershell -c ls"):
            verdict = self.authorize(command)
            self.assertTrue(verdict["allow"], command)
            self.assertNotIn("need_confirm", verdict, command)

    def test_confirm_prefixes(self):
        # 打开设置里的「执行高风险命令前先问我」之后才回到逐条确认
        self.write_webui_config({"confirm_high_risk_commands": True})
        handler = self.make_tools()
        authorize = lambda cmd: handler.authorize("run_command", {"command": cmd})
        self.assertTrue(authorize("powershell -Command dir")["need_confirm"])
        self.assertTrue(authorize("del 旧文件.txt")["need_confirm"])
        self.assertTrue(authorize("dir & del 旧文件.txt")["need_confirm"])
        self.assertTrue(authorize("@del 旧文件.txt")["need_confirm"])
        self.assertTrue(authorize("cmd /c powershell -c ls")["need_confirm"])
        self.assertTrue(authorize("C:\\Windows\\System32\\powershell.exe -c ls")["need_confirm"])
        self.assertNotIn("need_confirm", authorize("dir /b"))
        self.assertNotIn("need_confirm", authorize("findstr /s TODO *.md"))
        # 硬拦截永远生效：blocked_prefixes 不受这个开关影响
        blocked = authorize("format c: /q")
        self.assertFalse(blocked["allow"])
        self.assertEqual(blocked["status"], "denied")

    def test_disabled(self):
        self.write_agent_config({"command": {"enabled": False}})
        handler = self.make_tools()
        verdict = handler.authorize("run_command", {"command": "dir"})
        self.assertFalse(verdict["allow"])

    def test_run_echo_and_audit(self):
        output, meta = self.handler.run("run_command", {"command": "echo webui-selfcheck"})
        self.assertIn("webui-selfcheck", output)
        self.assertEqual(meta["exitCode"], 0)
        audit = os.path.join(self.base, "logs", "commands.log")
        self.assertTrue(os.path.isfile(audit))
        with open(audit, "r", encoding="utf-8") as handle:
            self.assertIn("webui-selfcheck", handle.read())

    def test_empty_command(self):
        self.assertFalse(self.authorize("")["allow"])


class TestFileTools(WebUITestCase):
    def test_outside_allowed_by_default(self):
        handler = self.make_tools()
        outside = os.path.join(self.tmp, "外部目录", "笔记.txt")
        output, meta = handler.run("write_file", {"path": outside, "content": "可以写\n"})
        self.assertTrue(meta["created"])
        self.assertTrue(os.path.isfile(outside))
        text, _read = handler.run("read_file", {"path": outside})
        self.assertIn("可以写", text)

    def test_workspace_sandbox(self):
        self.write_webui_config({"allow_outside_workspace": False})
        handler = self.make_tools()
        inside = handler.resolve("子目录\\a.txt")
        self.assertTrue(inside.startswith(self.workspace))
        with self.assertRaises(tools_module.ToolError):
            handler.resolve("C:\\Windows\\win.ini")

    def test_outside_allowed_when_enabled(self):
        self.write_webui_config({"allow_outside_workspace": True})
        handler = self.make_tools()
        resolved = handler.resolve(self.tmp)
        self.assertEqual(os.path.normcase(resolved), os.path.normcase(self.tmp))

    def test_write_read_snapshot(self):
        handler = self.make_tools()
        target = os.path.join(self.workspace, "笔记.md")
        with open(target, "w", encoding="utf-8") as handle:
            handle.write("第一版\n")
        output, meta = handler.run("write_file", {"path": target, "content": "第二版\n新行\n"})
        self.assertFalse(meta["created"])
        self.assertTrue(os.path.isfile(meta["snapshot"]))
        with open(meta["snapshot"], "r", encoding="utf-8") as handle:
            self.assertEqual(handle.read(), "第一版\n")
        self.assertEqual(meta["added"], 2)
        self.assertTrue(any(row["kind"] == "add" for row in meta["diff"]))
        text, read_meta = handler.run("read_file", {"path": target})
        self.assertIn("1\t第二版", text)
        self.assertEqual(read_meta["lines"], 3)

    def test_create_only_refuses_overwrite(self):
        handler = self.make_tools()
        target = os.path.join(self.workspace, "已有.txt")
        with open(target, "w", encoding="utf-8") as handle:
            handle.write("x")
        with self.assertRaises(tools_module.ToolError):
            handler.run("write_file", {"path": target, "content": "y", "create_only": True})

    def test_docx_round_trip(self):
        handler = self.make_tools()
        target = os.path.join(self.workspace, "周报.docx")
        handler.run("write_file", {"path": target, "content": "本周结论\n完成三项任务"})
        self.assertTrue(os.path.isfile(target))
        text, meta = handler.run("read_file", {"path": target})
        self.assertEqual(meta["kind"], "docx")
        self.assertIn("本周结论", text)
        self.assertIn("完成三项任务", text)

    def test_xlsx_round_trip(self):
        handler = self.make_tools()
        target = os.path.join(self.workspace, "表.xlsx")
        table = "| 姓名 | 部门 |\n| --- | --- |\n| 张三 | 研发 |\n| 李四 | 市场 |"
        handler.run("write_file", {"path": target, "content": table})
        text, meta = handler.run("read_file", {"path": target})
        self.assertEqual(meta["kind"], "xlsx")
        self.assertIn("姓名", text)
        self.assertIn("张三", text)
        self.assertIn("市场", text)
        self.assertEqual(tools_module.office.parse_rows(table)[0], ["姓名", "部门"])

    def test_write_pptx_tool_with_notes_and_read_back(self):
        handler = self.make_tools()
        target = os.path.join(self.workspace, "课件", "分数的意义.pptx")
        output, meta = handler.run("write_file", {"path": target, "content": OUTLINE})
        self.assertEqual(meta["kind"], "pptx")
        self.assertEqual(meta["slides"], 2)
        self.assertTrue(meta["created"])
        self.assertTrue(os.path.isfile(target))
        self.assertIn("生成幻灯片 2 张", output)
        self.assertTrue(meta.get("notes_path") and os.path.isfile(meta["notes_path"]))
        with open(meta["notes_path"], "r", encoding="utf-8") as handle:
            self.assertIn("开场复习平均分", handle.read())

        text, read_meta = handler.run("read_file", {"path": target})
        self.assertEqual(read_meta["kind"], "pptx")
        self.assertIn("分数的意义", text)
        self.assertIn("生活中的分数", text)

        # 覆盖已有课件：自动快照 + 张数变化
        again, meta2 = handler.run("write_file", {"path": target, "content": "# 只有一页\n- 改版\n"})
        self.assertFalse(meta2["created"])
        self.assertEqual(meta2["slides"], 1)
        self.assertTrue(os.path.isfile(meta2["snapshot"]))

    def test_write_pptx_tool_with_template(self):
        handler = self.make_tools()
        template = os.path.join(self.workspace, "学校模板.pptx")
        handler.run("write_file", {"path": template, "content": "# 模板页\n- 保留\n"})
        target = os.path.join(self.workspace, "套模板.pptx")
