        with open(os.path.join(self.workspace, "b.md"), "w", encoding="utf-8") as handle:
            handle.write("x")
        os.makedirs(os.path.join(self.workspace, "子目录"))
        text, meta = handler.run("list_dir", {"path": self.workspace})
        self.assertEqual(meta["count"], 2)
        self.assertIn("[目录]", text)
        self.assertIn("b.md", text)
        filtered, meta2 = handler.run("list_dir", {"path": self.workspace, "pattern": "*.md"})
        self.assertEqual(meta2["count"], 1)


