    def test_browse_lists_drives_shortcuts_and_filters(self):
        port = self.start_http()
        root = get_json(port, "/api/browse")
        self.assertTrue(root["drives"])
        self.assertEqual(root["workspace"], self.workspace)
        self.assertTrue(any(item["name"] == "工作区" for item in root["shortcuts"]))

        with open(os.path.join(self.workspace, "笔记.md"), "w", encoding="utf-8") as handle:
            handle.write("x")
        with open(os.path.join(self.workspace, "照片.png"), "wb") as handle:
            handle.write(tiny_png())
        os.makedirs(os.path.join(self.workspace, "子目录"))

        listing = get_json(port, "/api/browse?path=" + urllib.parse.quote(self.workspace))
        names = [item["name"] for item in listing["entries"]]
        self.assertIn("子目录", names)
        self.assertIn("笔记.md", names)
        self.assertTrue(listing["entries"][0]["dir"], "目录应排在文件前面")
        self.assertEqual(os.path.normcase(listing["path"]), os.path.normcase(self.workspace))

        images = get_json(port, "/api/browse?filter=image&path=" + urllib.parse.quote(self.workspace))
        image_names = [item["name"] for item in images["entries"]]
        self.assertIn("照片.png", image_names)
        self.assertNotIn("笔记.md", image_names)
        self.assertIn("子目录", image_names)      # 目录始终保留，便于继续翻

        parent = get_json(port, "/api/browse?path=" + urllib.parse.quote(self.workspace))["parent"]
        self.assertEqual(os.path.normcase(parent), os.path.normcase(self.tmp))
        with self.assertRaises(urllib.error.HTTPError):
            get_json(port, "/api/browse?path=" + urllib.parse.quote(os.path.join(self.tmp, "没有这个目录")))

    def test_upload_generic_and_blocked_types(self):
        port = self.start_http()
        payload = base64.b64encode("第一课教案".encode("utf-8")).decode("ascii")
        result = post_json(port, "/api/upload", {"name": "教案.docx", "data": payload})
        self.assertTrue(result["ok"])
