    def test_open_endpoint_guards(self):
        port = self.start_http()
        # 不存在的文件：直接拒绝，不会真的去打开
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            post_json(port, "/api/open", {"path": os.path.join(self.workspace, "没有.pptx")})
        self.assertEqual(ctx.exception.code, 400)
        # 可执行文件类型：拒绝直接运行
        script = os.path.join(self.workspace, "run.bat")
