    def test_skills_list_save_and_delete(self):
        port = self.start_http()
        self.assertEqual(get_json(port, "/api/skills")["skills"], [])

        saved = post_json(port, "/api/skills/save", {
            "name": "三年级数学",
            "description": "三年级数学课件与练习要求",
            "content": "- 课件每页字少字号大\n- 练习难度 6:3:1"})
        self.assertTrue(saved["ok"])
        self.assertTrue(os.path.isfile(os.path.join(self.base, "skills", "三年级数学", "SKILL.md")))
        skills = get_json(port, "/api/skills")["skills"]
        self.assertEqual(len(skills), 1)
        self.assertEqual(skills[0]["name"], "三年级数学")
        self.assertIn("6:3:1", skills[0]["content"])
        self.assertTrue(skills[0]["editable"])

        # 非法名称与空内容都要被拒绝
        for payload in ({"name": "a/b", "content": "x"}, {"name": "ok", "content": "   "}):
            with self.assertRaises(urllib.error.HTTPError) as ctx:
                post_json(port, "/api/skills/save", payload)
            self.assertEqual(ctx.exception.code, 400)

        removed = post_json(port, "/api/skills/delete", {"name": "三年级数学"})
        self.assertTrue(removed["ok"])
        self.assertEqual(get_json(port, "/api/skills")["skills"], [])
        with self.assertRaises(urllib.error.HTTPError):
            post_json(port, "/api/skills/delete", {"name": "不存在的技能"})

