    def test_full_skill_list_survives_a_round_trip(self):
        """界面把"默认全开"落成显式列表之后，服务端必须原样收下——不能当成空。

        老师那侧的链路是：会话 skills 为空 = 服务端全注入（core._choose_skills）。
        界面第一次点掉某个技能时会写回"全部减这一个"，这份完整列表要是被服务器
        当空列表吞掉，就又是"全开"，老师会看到刚关掉的技能自己回来了。
        """
        port = self.start_http()
        for name in ("技能甲", "技能乙", "技能丙"):
            post_json(port, "/api/skills/save",
                      {"name": name, "description": "占位", "content": "正文"})
        names = [skill["name"] for skill in get_json(port, "/api/skills")["skills"]]
        self.assertEqual(len(names), 3)
        session = post_json(port, "/api/session/new", {"title": "全开"})["session"]
        saved = post_json(port, "/api/session/skills", {"id": session["id"], "skills": names})
        self.assertEqual(saved["session"]["skills"], names)
        # 重新读一遍：不是只回了个好看的响应
        reread = get_json(port, "/api/session?id=" + session["id"])["session"]
        self.assertEqual(reread["skills"], names)
        # 显式列了全部，_choose_skills 就按这份列表走，一条都不许丢
        runner = core.AgentRun(self.settings(), reread, None, None, lambda event: None,
                               lambda *args: True, threading.Event())
        chosen = [skill.name for skill in runner._choose_skills("随便问一句")]
        self.assertEqual(chosen, names)

