    def test_parametric_equation(self):
        """参数方程：x = cos(t), y = sin(t) 画出来必须是单位圆。"""
        import plot as plot_module
        payload, error = plot_module.build({"kind": "equation",
                                            "expression": "x = cos(t), y = sin(t)"})
