        self.assertEqual(payload["kind"], "parametric")
        points = [point for line in payload["segments"] for point in line]
        self.assertGreater(len(points), 400)
        worst = max(abs((x * x + y * y) ** 0.5 - 1.0) for x, y in points)
        self.assertLess(worst, 0.005, "离单位圆最远差了 %.4f" % worst)
