    def test_polar_equation(self):
        """极坐标：r = 1 + cos(θ) 是心形线，x 从 -0.25 到 2。"""
        import plot as plot_module
        for text in ("r = 1 + cos(theta)", "r = 1 + cos(θ)", "r = 1 + cos(t)"):
            payload, error = plot_module.build({"kind": "equation", "expression": text})
            self.assertFalse(error, "%s：%s" % (text, error))
            self.assertEqual(payload["kind"], "polar", text)
            points = [point for line in payload["segments"] for point in line]
            xs = [point[0] for point in points]
            self.assertAlmostEqual(min(xs), -0.25, places=2, msg=text)
            self.assertAlmostEqual(max(xs), 2.0, places=2, msg=text)
            ys = [point[1] for point in points]
            # y = (1+cosθ)·sinθ 的极值是 ±3√3/4 ≈ ±1.299（θ = ±60° 处），不是 ±1
            self.assertAlmostEqual(min(ys), -1.299, places=2, msg=text)
            self.assertAlmostEqual(max(ys), 1.299, places=2, msg=text)

