    def test_equation_curves(self):
        """方程（隐函数）曲线：圆、椭圆/双曲线、以及把 y=x^2 也当方程画。"""
        import plot as plot_module
        payload, error = plot_module.build({"kind": "equation",
                                            "expression": "x^2 + y^2 = 4"})
        self.assertFalse(error, error)
        self.assertEqual(payload["kind"], "equation")
        points = [point for line in payload["segments"] for point in line]
        self.assertGreater(len(points), 40, "圆应该有一圈采样点")
        # 每个点到原点的距离都接近 2（隐函数曲线是盖在真实曲线上的）
        for x, y in points[:40]:
            self.assertAlmostEqual((x * x + y * y) ** 0.5, 2.0, places=2)
        # 四个象限都画到了（不是只有一段弧）
        self.assertTrue(any(x > 1.5 for x, _y in points) and any(x < -1.5 for x, _y in points))

        for text in ("x^2/4 - y^2/9 = 1", "y = x^2"):
            payload, error = plot_module.build({"kind": "equation", "expression": text})
            self.assertFalse(error, "%s：%s" % (text, error))
            self.assertTrue(payload["segments"], text)

