    def test_figure_meta_is_set_before_any_return(self):
        """`svg.__fig` 必须在 buildFigureSvg 的**所有 return 之前**挂好。

        几何分支是提前 return 的，挂在函数末尾的话几何图形永远拿不到换算信息，
        表现是"几何工具点了没反应"（换算时 __fig 是 undefined）。
        这个坑埋了好几轮，直到几何要点击才暴露出来。
        """
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        start = app.index("function buildFigureSvg(figure) {")
        end = app.index("\n  function ", start + 10)
        body = app[start:end]
        # 立体图形走自己的相机（solidView），不参与 __fig 这条约定，先把它那段摘掉
        solid = body.index("if (figure.kind === 'solid') {")
        solid_end = body.index("return svg;", solid) + len("return svg;")
        body = body[:solid] + body[solid_end:]
        meta = body.index("svg.__fig = {")
        returns = [index for index in range(len(body))
                   if body.startswith("return svg;", index)]
        self.assertTrue(returns, "buildFigureSvg 里应该有 return svg")
        self.assertLess(meta, min(returns),
                        "svg.__fig 挂在第一个 return 之后了，几何图形会拿不到")


    def test_angle_reports_exact_values(self):
        """量角要给 sin/cos 的精确值（分数或根号），不能只给小数。"""
