        angle = [s for s in payload["shapes"] if s["type"] == "angle"][0]
        self.assertEqual(angle["sin"], "3/5")
        self.assertEqual(angle["cos"], "4/5")
        self.assertTrue(angle["exact"])
        payload, _error = plot_module.build({
            "kind": "geometry",
            "shapes": ["A(0,0)", "B(1,0)", "C(0.5,0.8660254)", "angle A B C"]})
        angle = [s for s in payload["shapes"] if s["type"] == "angle"][0]
        self.assertEqual(angle["nice"], 60)
        self.assertEqual(angle["sin"], "\u221a3/2")
        self.assertEqual(angle["cos"], "1/2")

