    def test_figure_meta_group_created_first(self):
        """`svg.__fig` 里带了 group，所以 group 必须先创建好。

        老毛病：group 建晚了 / __fig 挂在 return 之后，二维换算一进来就是 undefined。
        现在这块面板只剩立体（走 solidView，不参与 __fig 这条约定），下面那段是
        **给会话里回放的老图**留的路径；这条测试盯住它别写坏。
        """
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        start = app.index("function buildFigureSvg(figure) {")
        end = app.index("\n  function ", start + 10)
        body = app[start:end]
        # 立体图形走自己的相机（solidView），不参与 __fig 这条约定，先把它那段摘掉
        solid = body.index("if (figure.kind === 'solid') {")
        solid_end = body.index("return svg;", solid) + len("return svg;")
        body = body[:solid] + body[solid_end:]
        self.assertLess(body.index("var group = svgEl"),
                        body.index("svg.__fig = {"), "group 要在 __fig 之前建好")
        self.assertLess(body.index("svg.__fig = {"),
                        body.index("return svg;"), "__fig 要在所有 return 之前挂好")
        # 二维视图（view）已经删掉，这里不许再引用它——引用就是 ReferenceError
        self.assertNotIn("if (view)", body, "旧的二维视图状态已经删了")





