    def test_constraint_checks_membership_first(self):
        """约束拖动前必须**先判断点在不在那条线/那个面上**，不在就明确拒绝。"""
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        # 用**冻结**的线/面判断归属：这样端点也能拖，而线本身不会跟着跑
        start = app.index("function pointOnConstraint")
        body = app[start:app.index("\n  }", start)]
        self.assertIn("constraint.line", body)
        self.assertIn("constraint.plane", body)
        self.assertNotIn("names.indexOf(point.name) >= 0", body,
                         "不能把定义点排除掉：一条棱上就那两个点，排除完就没得拖了")
        # 冻结写在 confirmConstraint 里：确定的那一刻把线/面的坐标抄下来
        freeze = app[app.index("function confirmConstraint"):]
        freeze = freeze[:freeze.index("function pointOnConstraint")]
        self.assertIn("line: spec.constraint === 'line'", freeze,
                      "确定时要把线的位置冻结下来")
        self.assertIn("plane: spec.constraint === 'face'", freeze)
        self.assertIn("function confirmConstraint", app)
        self.assertIn("function armSolid", app)
        # 工具再点一下要能取消高亮、清掉选择
        arm = app[app.index("function armSolid"):]
        arm = arm[:arm.index("\n  }")]
        self.assertIn("solidState.constraint = null", arm)
        self.assertIn("solidState.armed && solidState.armed.kind === kind", arm)
        # 线的拖动：把鼠标投到"A、B 投影后的线段"上，保证只能沿线走
        drag = app[app.index("function solidDragMove"):]
        drag = drag[:drag.index("\n  }")]
        self.assertIn("ratio", drag)
        self.assertIn("solidRayAt", app, "面上的拖动要解射线与平面的交点")

    def test_manual_circle_and_sphere(self):
        """手画圆和球。

        以前立体语法里**没有独立的圆**，球也只能写半径 —— 老师没法"手动画一个圆"。
        现在：circle3 A B C 过三点的圆，sphere O A 球心加球面上一点。
        """
        import math

        # 外接圆心要算对（符号写反会得到"对面那个点"，半径一样，光看半径发现不了）
        cases = [
            (["A(0,0,0)", "B(2,0,0)", "C(0,2,0)"], (1, 1, 0), math.sqrt(2)),
            (["A(0,0,0)", "B(1,0,0)", "C(0,1,1)"], (0.5, 0.5, 0.5), math.sqrt(0.75)),
        ]
        for trio, want_center, want_radius in cases:
            payload, error = plot_module.build(
                {"kind": "solid", "shapes": trio + ["circle3 A B C"]})
            self.assertEqual(error, "")
            curve = payload["curves"][0]
            for index in range(3):
                self.assertAlmostEqual(curve["center"][index], want_center[index], places=4,
                                       msg="圆心算错了：%s" % (curve["center"],))
            self.assertAlmostEqual(curve["radius"], want_radius, places=4)

        # 三点共线要明确拒绝
        _, message = plot_module.build(
            {"kind": "solid", "shapes": ["A(0,0,0)", "B(1,0,0)", "C(2,0,0)", "circle3 A B C"]})
        self.assertIn("一条直线", message)

        # 球：球心 + 球面上一点
        payload, error = plot_module.build(
            {"kind": "solid", "shapes": ["O(0,0,0)", "P(0,0,4)", "sphere O P"]})
        self.assertEqual(error, "")
        self.assertAlmostEqual(payload["curves"][0]["radius"], 4.0, places=4)

        # AI 那边也要看得到（系统提示 + 技能 + 工具描述）
        with open(os.path.join(HERE, "core.py"), encoding="utf-8") as handle:
            core = handle.read()
        self.assertIn("圆柱", core, "系统提示里没提圆柱/圆锥/球")
        self.assertIn("circle3", core)
        self.assertIn("cylinder", plot_module.SOLID_HELP)
        with open(os.path.join(HERE, "..", "skills", "figure-first", "SKILL.md"),
                  encoding="utf-8") as handle:
            skill = handle.read()
        self.assertIn("圆柱", skill)
        self.assertIn("circle3", skill)
        # 工具栏上要能点出来
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        self.assertIn("circle3: { label: '画圆'", app)
        self.assertIn("sphereoa: { label: '画球'", app)

    def test_round_solids(self):
        """圆柱 / 圆锥 / 球：以前**完全没有**这三种（老师反馈"画不出来"）。

        曲面用多边形逼近，逼近出来的顶点标成 hidden —— 不标的话一个圆
        36 个字母，图就糊了。
        """
        import math

        payload, error = plot_module.build(
            {"kind": "solid", "shapes": ["O(0,0,0)", "cylinder O 3 5"]})
        self.assertEqual(error, "")
        self.assertGreater(len(payload["edges"]), 50, "圆柱要有侧棱和上下底圆")
        hidden = [point for point in payload["points"] if point.get("hidden")]
        self.assertTrue(hidden, "逼近出来的顶点要标 hidden")
        # 表面积 / 体积对着公式验（多边形逼近，允许 1% 误差）
        area = payload["measures"]["area"]
        volume = payload["measures"]["volume"]
        self.assertLess(abs(area - 48 * math.pi) / (48 * math.pi), 0.01,
                        "圆柱表面积应该接近 48π，实际 %s" % area)
        self.assertLess(abs(volume - 45 * math.pi) / (45 * math.pi), 0.01,
                        "圆柱体积应该接近 45π，实际 %s" % volume)

        cone, error = plot_module.build(
            {"kind": "solid", "shapes": ["O(0,0,0)", "cone O 3 5"]})
        self.assertEqual(error, "")
        self.assertLess(abs(cone["measures"]["volume"] - 15 * math.pi) / (15 * math.pi),
                        0.01, "圆锥体积应该接近 15π")

        ball, error = plot_module.build(
            {"kind": "solid", "shapes": ["O(0,0,0)", "sphere O 3"]})
        self.assertEqual(error, "")
        self.assertGreater(len(ball["edges"]), 50, "球要有经纬线")
        # 球是线框：那几个大圆**不是**面，不能算出一个假的表面积
        self.assertIsNone(ball["measures"].get("area"),
                          "球画的是线框，不该报表面积")
        self.assertIsNone(ball["measures"].get("volume"))

        # 参数写错要说人话
        for bad in ("cylinder O 3", "sphere O", "cylinder O 0 5", "cone O 3 0"):
            _, message = plot_module.build({"kind": "solid",
                                            "shapes": ["O(0,0,0)", bad]})
            self.assertTrue(message, "「%s」应该报错" % bad)

    def test_solid_measures(self):
        """体积和表面积：拿有标准答案的立体对。"""
        import plot as plot_module
        cases = [
            ("长方体 4x3x2", ["A(0,0,0)", "B(4,0,0)", "C(4,3,0)", "D(0,3,0)",
                            "box A B C D 2"], 52.0, 24.0),
            ("正方体 2", ["A(0,0,0)", "B(2,0,0)", "C(2,2,0)", "D(0,2,0)",
                         "box A B C D 2"], 24.0, 8.0),
            ("三棱柱底 3-4-5 高 5", ["A(0,0,0)", "B(3,0,0)", "C(0,4,0)",
                                   "prism A B C 5"], 72.0, 30.0),
        ]
        for name, shapes, want_area, want_volume in cases:
            payload, error = plot_module.build({"kind": "solid", "shapes": shapes})
            self.assertFalse(error, "%s：%s" % (name, error))
            measures = payload["measures"]
            self.assertAlmostEqual(measures["area"], want_area, places=2, msg=name)
            self.assertAlmostEqual(measures["volume"], want_volume, places=2, msg=name)
        # 正四面体边长 1：表面积 √3、体积 1/(6√2)
        import math as math_module
        payload, _error = plot_module.build({
            "kind": "solid",
            "shapes": ["A(0,0,0)", "B(1,0,0)", "C(0.5,0.8660254037844386,0)",
                       "D(0.5,0.28867513459481287,0.816496580927726)",
                       "face A B C", "face A B D", "face A C D", "face B C D"]})
        self.assertAlmostEqual(payload["measures"]["area"], math_module.sqrt(3), places=4)
        self.assertAlmostEqual(payload["measures"]["volume"], 1 / (6 * math_module.sqrt(2)),
                               places=4)

