    def test_dynamic_point_stays_draggable(self):
        """曲面上的动点：任何工具状态下都要拖得动。

        踩过两次：
          1. armSolid 会把 constraint 清空 —— 那个 constraint 正是"这个动点
             挂在哪个曲面上"，于是点一下「面面角」动点就拖不动了（只会转视角）；
          2. 动点表里存的是 {name,...}，pointOnConstraint 却判 constraint.point，
             永远 undefined —— 按下就返回，连拖动状态都进不去。
        """
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        # 动点要有自己的归属表，不能只挂在 constraint 上
        self.assertIn("dynamicPoints", app)
        self.assertIn("function constraintOfPoint", app)
        # 两个字段都要认
        self.assertIn("constraint.point || constraint.name", app)
        # 按下 / 拖动 / 松手三条路都要先查动点表
        self.assertIn("constraintOfPoint(point.name) || solidState.constraint", app)
        # 拖整条棱时 dragPoint 是空的（由 dragEdge 带），所以这里多一层三元：
        # 被拖的点有动点约束就用它，否则退回当前工具的约束。
        self.assertIn("(solidState.dragPoint ? constraintOfPoint(solidState.dragPoint) : null)",
                      app)
        # 松手不能因为"当前工具没约束"就直接返回
        self.assertIn("function solidDragEnd() {\n    if (!solidState.dragging) return;", app)
        # 动点约束没有 names 字段，不能硬读
        self.assertIn("(constraint.names || [])", app)

    def test_exact_never_hangs(self):
        """精确值的化简**绝不能卡住**。

        真踩过：动点坐标是 2.92 这种小数，还原成分数后 Exact.sqrt 会把
        "分子×分母"丢进 _squarefree 试除，那个数可以是几亿，试除要跑上千万次
        —— 请求永远不返回，前端表现成"角一动就消失"。
        """
        import calc as calc_module
        import plot as plot_module
        import time

        # 直接怼一个大数：必须在很短时间内返回，不许跑飞
        started = time.time()
        calc_module.Exact.rational(999999937 * 999999893).sqrt().format()
        self.assertLess(time.time() - started, 2.0, "大数开方卡住了")

        # 用动点坐标（小数）算角：这是真实的触发路径
        started = time.time()
        payload, error = plot_module.build(
            {"kind": "solid",
             "shapes": ["O(0,0,0)", "cylinder O 3 5", "A(-3,0,0)", "B(3,0,0)",
                        "M(0.7, 2.92, 5)", "\u7ebf\u7ebf\u89d2 A B O M"]})
        self.assertEqual(error, "")
        self.assertLess(time.time() - started, 2.0, "带小数的角算卡住了")
        angle = payload["angles"][0]
        self.assertIsNotNone(angle.get("degrees"), "度数必须给出来")

    def test_exact_sqrt_of_zero_is_zero(self):
        """√0 = 0。

        以前 _squarefree(0) 返回 (1, 1)，√0 被算成 1——线面角 90° 时
        cos 会跟着写成 1（sin=1 且 cos=1 是不可能同时成立的）。
        """
        import calc as calc_module
        self.assertEqual(calc_module.Exact.rational(0).sqrt().format(), "0")
        self.assertEqual(calc_module.Exact.rational(4).sqrt().format(), "2")
        self.assertEqual(calc_module.Exact.rational(2).sqrt().format(), "\u221a2")
        one = calc_module.Exact.rational(1)
        sine = calc_module.Exact.rational(1) / calc_module.Exact.rational(1).sqrt()
        cosine = (calc_module.Exact.rational(1) - sine * sine).sqrt()
        self.assertEqual(cosine.format(), "0", "sin=1 时 cos 必须是 0")

    def test_solid_is_reachable_from_show_figure(self):
        """show_figure 必须能画立体图形，而且**只剩**立体。

        以前 kind 的枚举只有 function / geometry —— AI 在**协议层面**就没法要
        立体图，只能往平面图形上凑（老师反馈"只会尝试在平面中生成"）。
        现在反过来：老师要求"AI 调用工具只准用新加的这个平面的"，平面那两项
        必须从枚举里拿掉，否则模型会挑老路走、新平面的依赖图永远用不上。
        """
        found = None
        for spec in tools_module.TOOL_SPECS:
            if spec["function"]["name"] == "show_figure":
                found = spec["function"]
        self.assertIsNotNone(found, "没有 show_figure 这个工具")
        kinds = found["parameters"]["properties"]["kind"]["enum"]
        self.assertEqual(kinds, ["solid"],
                         "show_figure 的 kind 只该剩 solid；平面有 plane 工具了")
        self.assertIn("kind=solid", found["description"], "描述里没讲怎么用 solid")
        self.assertIn("plane", found["description"], "要写明平面改用 plane 工具")
        # 提示和技能里也要讲，否则 AI 有了参数也想不到用
        with open(os.path.join(HERE, "core.py"), encoding="utf-8") as handle:
            core = handle.read()
        self.assertIn("kind=solid", core, "系统提示里没提立体图形")
        self.assertIn("只准用 plane", core, "系统提示里要写明平面一律用 plane")
        with open(os.path.join(HERE, "..", "skills", "figure-first", "SKILL.md"),
                  encoding="utf-8") as handle:
            skill = handle.read()
        self.assertIn("`solid`", skill, "figure-first 技能里没讲 solid")
        self.assertIn("plane_batch", skill, "figure-first 技能里没讲平面怎么画")

    def test_bad_expressions_explain_themselves(self):
        for text in ("", "sin(", "x +", "foo(x)", "x)(", "2 ** 3", "&"):
            _figure, error = plot_module.build({"kind": "function", "expression": text})
            self.assertTrue(error, "这个表达式本该报错：%r" % text)
            self.assertNotIn("Traceback", error)

    def test_no_eval_is_used(self):
        """表达式求值绝不能用 eval / exec：那是把工具面直接开成代码执行。"""
        with io.open(os.path.join(HERE, "plot.py"), encoding="utf-8") as handle:
            source = handle.read()
        self.assertNotIn("eval(", source)
        self.assertNotIn("exec(", source)
        self.assertNotIn("__import__", source)

    def test_function_sampling_splits_at_asymptotes(self):
        figure, error = plot_module.build({"kind": "function", "expression": "1/x"})
        self.assertEqual(error, "")
        self.assertEqual(len(figure["segments"]), 2, "1/x 的两支不能连成一条竖线")
        self.assertTrue(all(len(segment) > 1 for segment in figure["segments"]))
        figure, error = plot_module.build({"kind": "function", "expression": "sin(x)",
                                           "x_min": -3, "x_max": 3})
        self.assertEqual((figure["x_min"], figure["x_max"]), (-3, 3))
        self.assertLess(figure["y_min"], 0)
        self.assertGreater(figure["y_max"], 0)

    def test_geometry_syntax_and_aliases(self):
        figure, error = plot_module.build({"kind": "geometry", "shapes": [
            "A(0,0)", "B(4,0)", "C(4,3)", "seg A B", "线段 B C", "line C A",
            "angle A B C", "circle O 2", "O(0,0)"]})
        self.assertEqual(error, "")
        self.assertEqual([point["name"] for point in figure["points"]], ["A", "B", "C", "O"])
        kinds = [shape["type"] for shape in figure["shapes"]]
        self.assertEqual(kinds, ["segment", "segment", "line", "angle", "circle"])
        # 圆心到圆上一点：写成 circle O A 时半径要自己算
        figure, error = plot_module.build({"kind": "geometry",
                                           "shapes": ["A 0 0", "B 3 4", "circle A B"]})
        self.assertEqual(error, "")
        self.assertAlmostEqual(figure["shapes"][0]["radius"], 5.0, places=6)

    def test_geometry_errors_name_the_problem(self):
        for shapes, hint in (
                ([], "点"),
                (["seg A B"], "至少"),
                (["A(0,0)", "seg A B"], "B"),
                (["A(0,0)", "circle A 0"], "半径"),
                (["A(0,0)", "B(1,1)", "三角形 A B"], "三个点")):
            figure, error = plot_module.build({"kind": "geometry", "shapes": shapes})
            self.assertIsNone(figure, shapes)
            self.assertIn(hint, error, "%s 的报错要说到点子上：%s" % (shapes, error))

    def test_http_endpoint_only_serves_solids_and_points_at_the_plane(self):
        """/api/figure 只剩立体，平面 kind 一律**结构化拒绝并指路**到平面面板。

        **这是需求变更，不是放宽断言**：老师要求"把平面模块用来替换以前的函数、
        方程、平面几何模块"，所以原来"网页也能 POST kind=function 画函数"的行为
        被**故意取消**了——同一能力留两条入口，浏览器端就成了绕过收敛的后门。
        新行为必须和 AI 那边 show_figure 的 wrong_tool 拒绝一致：code=wrong_tool、
        说清收到的是什么、hint 里点名平面（POST /api/plane/apply）。
        """
        for body in ({"kind": "function", "expression": "2x + 1", "title": "一次函数"},
                     {"kind": "equation", "expression": "x^2 + y^2 = 4"},
                     {"kind": "geometry", "shapes": ["A(0,0)", "B(3,0)", "seg A B"]},
                     {}):
            with self.assertRaises(urllib.error.HTTPError) as ctx:
                post_json(self.port, "/api/figure", body)
            self.assertEqual(ctx.exception.code, 400, body)
            payload = json.loads(ctx.exception.read().decode("utf-8"))
            self.assertFalse(payload["ok"], body)
            error = payload["errors"][0]
            self.assertEqual(error["code"], "wrong_tool", body)
            self.assertEqual(error["path"], "kind", body)
            self.assertIn("立体", error["message"], "要说清这条接口只剩立体")
            self.assertIn("plane", error["hint"], "错误里要指路到平面（plane）")
        # 立体照旧：一次请求就能拿到整张图
        result = post_json(self.port, "/api/figure",
                           {"kind": "solid",
                            "shapes": ["A(0,0,0)", "B(4,0,0)", "C(4,3,0)", "D(0,3,0)",
                                       "box A B C D 3"],
                            "title": "长方体"})
        figure = result["figure"]
        self.assertEqual(figure["kind"], "solid")
        self.assertEqual(figure["title"], "长方体")
        self.assertEqual(len(figure["points"]), 8)
        self.assertEqual(len(figure["edges"]), 12)
        self.assertEqual(len(figure["faces"]), 6)
        # 立体自己的报错还是 400 一句中文（不是 wrong_tool）
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            post_json(self.port, "/api/figure", {"kind": "solid", "shapes": ["seg A B"]})
        self.assertEqual(ctx.exception.code, 400)

    def test_show_figure_refuses_the_plane_and_points_at_the_plane_tool(self):
        """show_figure 收到平面请求必须**拒绝并指路**，不能默默画一张。

        这是老师明确要求的："ai 调用工具只准用新加的这个平面的"。
        同一能力留着两条入口，模型就会挑熟悉的那条老路，新平面的依赖图
        （改父对象、交点跟着动）就永远用不上——所以要真的挡住。
        """
        handler = self.make_tools()
        handler.session = {}
        events = []
        handler.emit = events.append
        for args in ({"kind": "function", "expression": "sin(x)"},
                     {"kind": "geometry", "shapes": ["A(0,0)", "B(3,0)", "poly A B"]}):
            text, meta = handler.run("show_figure", args)
            payload = json.loads(text)
            self.assertFalse(payload["ok"], args)
            error = payload["errors"][0]
            self.assertEqual(error["code"], "wrong_tool")
            self.assertIn("plane", error["hint"], "错误里要写明改用 plane 工具")
            self.assertEqual(meta["ok"], False)
        self.assertEqual(events, [], "被拒的平面图形不能推 figure 事件给网页")

        # 立体照旧（它不在"平面"范围内）
        text, meta = handler.run("show_figure", {"kind": "solid",
                                                 "shapes": ["A(0,0,0)", "B(1,0,0)", "C(0,1,0)",
                                                            "face A B C"]})
        self.assertEqual(meta["kind"], "figure")
        self.assertEqual(meta["figure_kind"], "solid")
        self.assertEqual(events[-1]["t"], "figure")
        self.assertIn("作图面板", text, "要说清楚画到哪去了，别让老师以为画在白板上")

    def test_tool_is_authorized_and_visible_in_the_ui(self):
        handler = self.make_tools()
        self.assertTrue(handler.authorize("show_figure", {"kind": "solid"})["allow"])
        self.assertTrue(handler.authorize("plane", {"action": "query_state"})["allow"])
        names = [spec["function"]["name"] for spec in handler.specs()]
        self.assertIn("show_figure", names)
        self.assertIn("plane", names)
        app = io.open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8")
        with app:
            source = app.read()
        self.assertIn("show_figure: 'chart'", source, "工具卡片要有个图标")
        self.assertIn("case 'figure'", source, "页面上要认 figure 事件")
        # 平面工具没加进 DESKTOP_TOOLS：它只改平面状态，不碰文件/键鼠，
        # 进了那一组就要在 app.js 里配图标、还要走「动手前先问我」的确认，都不合适。
        self.assertNotIn("plane", tools_module.DESKTOP_TOOLS)
        self.assertNotIn("plane_batch", tools_module.DESKTOP_TOOLS)

    def test_classroom_materials_lists_the_three_folders(self):
        board = os.path.join(self.workspace, "板书")
        os.makedirs(board)
        with open(os.path.join(board, "板书-1.png"), "wb") as handle:
            handle.write(b"x")
        result = get_json(self.port, "/api/classroom/materials")
        by_key = {item["key"]: item for item in result["folders"]}
        self.assertEqual(sorted(by_key), ["board", "marker", "shot"])
