    def test_reasoning_effort_end_to_end(self):
        """推理等级：能在会话里选、会真的发给接口、也能在设置里改默认值。"""
        # 1) 设置里的默认值可以保存并回显
        response = post_json(self.port, "/api/settings", {"settings": {"reasoning_effort": "medium"}})
        self.assertEqual(response["config"]["reasoningEffort"], "medium")
        self.assertEqual(response["config"]["reasoningEfforts"],
                         ["minimal", "low", "medium", "high", "max"])

        # 2) 新会话沿用默认值，改成 high 之后存得住
        session = post_json(self.port, "/api/session/new", {"title": "推理等级"})["session"]
        self.assertEqual(session["effort"], "medium")
        changed = post_json(self.port, "/api/session/effort",
                            {"id": session["id"], "effort": "high"})["session"]
        self.assertEqual(changed["effort"], "high")
        self.assertEqual(get_json(self.port, "/api/session?id=" + session["id"])["session"]["effort"],
                         "high")
        with self.assertRaises(urllib.error.HTTPError):        # 非法等级直接拒绝
            post_json(self.port, "/api/session/effort", {"id": session["id"], "effort": "ultra"})

        # 3) 真的出现在发给模型的请求里，并且 start 事件把实际等级告诉界面
        self.upstream.script = [answer_round("好。")]
        self.upstream.requests = []
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "你好"})
        self.assertEqual(self.upstream.requests[0]["reasoning_effort"], "high")
        start = [event for event in events if event["t"] == "start"][0]
        self.assertEqual(start["effort"], "high")

        # 4) 选“默认”就不再带这个参数（不改动接口行为）
        post_json(self.port, "/api/session/effort", {"id": session["id"], "effort": ""})
        post_json(self.port, "/api/settings", {"settings": {"reasoning_effort": ""}})
        self.upstream.requests = []
        sse_chat(self.port, {"sessionId": session["id"], "text": "再说一次"})
        self.assertNotIn("reasoning_effort", self.upstream.requests[0])

    def test_reasoning_effort_falls_back_when_gateway_rejects_it(self):
        """网关不认 reasoning_effort 时要自动去掉参数重试，并如实说明。"""
        session = post_json(self.port, "/api/session/new",
                            {"title": "不支持的接口", "effort": "high"})["session"]
        self.upstream.script = [
            {"error": {"message": "Unrecognized request argument: reasoning_effort"}, "__status__": 400},
            answer_round("去掉参数也能回答。"),
        ]
        self.upstream.requests = []
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "你好"})
        self.assertIn("reasoning_effort", self.upstream.requests[0])
        self.assertNotIn("reasoning_effort", self.upstream.requests[1])     # 第二次已经去掉
        self.assertTrue(any(event["t"] == "notice" and "reasoning_effort" in event["message"]
                            for event in events))
        turns = [event for event in events if event["t"] == "turn"]
        self.assertEqual(turns[-1]["message"]["content"], "去掉参数也能回答。")

    def test_subagent_inherits_reasoning_effort(self):
        """子代理要沿用主代理选定的推理等级。"""
        arguments = json.dumps({"task": "写一句话", "role": "写手"}, ensure_ascii=False)
        main_rounds = [tool_round("run_subagent", arguments, call_id="sub_1"),
                       answer_round("子代理已经写完。")]
        sub_rounds = [answer_round("一句话。")]

        def scripted(request):
            names = [spec["function"]["name"] for spec in request.get("tools") or []]
            return sub_rounds if "run_subagent" not in names else main_rounds.pop(0)

        self.upstream.script = [scripted]
        self.upstream.requests = []
        session = post_json(self.port, "/api/session/new",
                            {"title": "子代理等级", "effort": "low"})["session"]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "派个子代理"})
        self.assertTrue(any(event["t"] == "sub_done" for event in events))
        self.assertTrue(self.upstream.requests)
        self.assertTrue(all(request.get("reasoning_effort") == "low"
                            for request in self.upstream.requests),
                        [request.get("reasoning_effort") for request in self.upstream.requests])

    def test_workspaces_registry(self):
        """工作区是「登记在册的文件夹」：新建 / 添加 / 切换 / 重命名 / 移除，和 DSH 一致。"""
        settings = self.settings()
        first = os.path.join(self.tmp, "课件")
        second = os.path.join(self.tmp, "成绩")
        os.makedirs(first)
        os.makedirs(second)
        settings.remember_workspace(first, "高一数学")
        settings.remember_workspace(second)
        settings.reload()
        entries = settings.workspaces()
        self.assertEqual([entry["path"] for entry in entries],
                         [core.canonical_path(second), core.canonical_path(first)])
        self.assertEqual(entries[1]["title"], "高一数学")
        self.assertEqual(settings.workspace_title(first), "高一数学")
        self.assertEqual(settings.workspace_title(second), "成绩")

        # 同一个目录的不同写法只登记一次；再切一次提到最前
        settings.remember_workspace(os.path.join(self.tmp, "课件") + os.sep)
        settings.reload()
        self.assertEqual(len(settings.workspaces()), 2)
        self.assertEqual(settings.workspaces()[0]["path"], core.canonical_path(first))
        self.assertEqual(settings.workspaces()[0]["title"], "高一数学")   # 名字不会因为再切一次丢掉

        # 重命名：重名要报错
        with self.assertRaises(ValueError):
            settings.rename_workspace(second, "高一数学")
        settings.rename_workspace(second, "高二数学")
        settings.reload()
        self.assertEqual(settings.workspace_title(second), "高二数学")

        # 移除只是从列表里去掉，不动文件夹
        settings.forget_workspace(second)
        settings.reload()
        self.assertEqual([entry["path"] for entry in settings.workspaces()],
                         [core.canonical_path(first)])
        self.assertTrue(os.path.isdir(second))

        # 新建工作区：真的建文件夹，父目录可选
        parent = os.path.join(self.tmp, "工作区根")
        created = settings.create_workspace("公开课", parent)
        self.assertTrue(os.path.isdir(created))
        self.assertEqual(core.canonical_path(created),
                         core.canonical_path(os.path.join(parent, "公开课")))
        with self.assertRaises(ValueError):        # 名字不能为空
            settings.create_workspace("   ")
        # 名字里的非法字符会被去掉，不会跑出父目录
        safe = settings.create_workspace("a/b:c*d", parent)
        self.assertIn("abcd", os.path.basename(safe))

    def test_workspace_paths_are_canonical(self):
        """同一个文件夹的不同写法必须算一个工作区，否则侧栏会出现“重复的工作区”。"""
        messy = os.path.join(self.tmp, "课件") + os.sep
        other = os.path.join(self.tmp, "课件") + os.sep + "." + os.sep
        self.assertEqual(core.canonical_path(messy), core.canonical_path(other))
        self.assertEqual(core.canonical_path("  \"" + messy + "\"  "), core.canonical_path(messy))
        self.assertEqual(core.canonical_path(""), "")
        # 换大小写/斜杠写法也算同一个
        self.assertEqual(core.canonical_path(messy.replace(os.sep, "/")),
                         core.canonical_path(messy))

        settings = self.settings()
        settings.save_webui({"workspace_root": messy})
        settings.remember_workspace(messy)
        settings.remember_workspace(other)
        settings.reload()
        self.assertEqual(len(settings.workspaces()), 1)
        self.assertEqual(settings.public_config()["recentWorkspaces"], [core.canonical_path(messy)])

        # 新会话的 workspace 也要落成规范形式
        session = post_json(self.port, "/api/session/new",
                            {"title": "路径写法", "workspace": messy})["session"]
        self.assertEqual(session["workspace"], core.canonical_path(messy))
        summaries = get_json(self.port, "/api/state")["sessions"]
        self.assertEqual([item["workspace"] for item in summaries if item["id"] == session["id"]],
                         [core.canonical_path(messy)])

    def test_workspace_api_end_to_end(self):
        """通过接口新建 / 添加 / 重命名 / 移除工作区，并把状态切到新建的那个。"""
        parent = os.path.join(self.tmp, "工作区根")
        created = post_json(self.port, "/api/workspace/create",
                            {"name": "高一数学", "parent": parent})["config"]
        target = core.canonical_path(os.path.join(parent, "高一数学"))
        self.assertTrue(os.path.isdir(target))
        self.assertEqual(created["workspace"], target)                       # 建完就切过去
        self.assertEqual([entry["path"] for entry in created["workspaces"]][0], target)
        self.assertEqual(created["workspaces"][0]["title"], "高一数学")

        # 在这个工作区里新建的对话就落在它下面
        session = post_json(self.port, "/api/session/new", {"title": "第一节"})["session"]
        self.assertEqual(session["workspace"], target)

        # 添加一个已有文件夹
        existing = os.path.join(self.tmp, "成绩")
        os.makedirs(existing, exist_ok=True)
        added = post_json(self.port, "/api/workspace/add", {"path": existing})["config"]
        self.assertIn(core.canonical_path(existing),
                      [entry["path"] for entry in added["workspaces"]])

        # 重命名 + 重名报错 + 移除
        renamed = post_json(self.port, "/api/workspace/rename",
                            {"path": existing, "title": "高二成绩"})["config"]
        self.assertEqual([entry["title"] for entry in renamed["workspaces"]
                          if entry["path"] == core.canonical_path(existing)], ["高二成绩"])
        with self.assertRaises(urllib.error.HTTPError):
            post_json(self.port, "/api/workspace/rename",
                      {"path": existing, "title": "高一数学"})
        removed = post_json(self.port, "/api/workspace/remove", {"path": existing})["config"]
        self.assertNotIn(core.canonical_path(existing),
                         [entry["path"] for entry in removed["workspaces"]])
        self.assertTrue(os.path.isdir(existing))       # 只移除登记，不删文件夹

    def test_second_run_on_same_session_is_rejected(self):
        """同一个会话同时只能跑一个（两个窗口一起提问会互相覆盖历史，后写的赢）。"""
        session = post_json(self.port, "/api/session/new", {"title": "并发"})["session"]
        slow = threading.Event()
        release = threading.Event()

        def blocking_round(request):
            slow.set()
            release.wait(15)
            return answer_round("第一条回答")

        self.upstream.script = [blocking_round, answer_round("第二条回答")]
        first = {}

        def run_first():
            first["events"] = sse_chat(self.port, {"sessionId": session["id"], "text": "第一问"})

        thread = threading.Thread(target=run_first)
        thread.start()
        self.assertTrue(slow.wait(10), "第一个运行没有起来")
        with self.assertRaises(urllib.error.HTTPError) as caught:
            post_json(self.port, "/api/chat", {"sessionId": session["id"], "text": "第二问"})
        self.assertEqual(caught.exception.code, 409)
        release.set()
        thread.join(20)
        self.assertFalse(thread.is_alive())

        stored = get_json(self.port, "/api/session?id=" + session["id"])["session"]
        contents = [message.get("content") for message in stored["messages"]
                    if message.get("role") == "user"]
        self.assertEqual(contents, ["第一问"], "第二个提问不该写进会话")
        self.assertEqual([event["t"] for event in first["events"]][-1], "close")

    def test_dead_client_cancels_the_run(self):
        """浏览器休眠/关页面后不能一直挂着：写不出去就取消这次运行，把会话让出来。"""
        # 服务器启动时已经读过配置，这里直接改运行中的设置（等价于把 sse_write_timeout 设成 1 秒）
        self.http.app.settings.webui["sse_write_timeout"] = 1
        session = post_json(self.port, "/api/session/new", {"title": "断开"})["session"]
        started = threading.Event()
        flood = [{"choices": [{"delta": {"content": "内容" * 2000}}]} for _ in range(300)]
        flood.append({"choices": [{"delta": {}, "finish_reason": "stop"}], "usage": usage()})

        def blocking_round(request):
            started.set()
            return flood

        self.upstream.script = [blocking_round]
        payload = json.dumps({"sessionId": session["id"], "text": "写一大堆"}).encode("utf-8")
        connection = socket.create_connection(("127.0.0.1", self.port), timeout=10)
        try:
            connection.sendall(b"POST /api/chat HTTP/1.1\r\nHost: 127.0.0.1\r\n"
                               b"Content-Type: application/json\r\n"
                               b"Content-Length: %d\r\n\r\n" % len(payload) + payload)
            self.assertTrue(started.wait(10), "运行没有起来")
            # 连上但一个字都不读：socket 缓冲区写满后服务端会卡在 write 里
            deadline = time.time() + 30
            released = False
            while time.time() < deadline:
                try:
                    sse_chat(self.port, {"sessionId": session["id"], "text": "还在吗"}, timeout=10)
                    released = True
                    break
                except urllib.error.HTTPError as exc:
                    if exc.code != 409:
                        raise
                    time.sleep(0.5)
            self.assertTrue(released, "断开客户端后运行没有及时结束（会话一直占着）")
        finally:
            try:
                connection.close()
            except OSError:
                pass

    def test_parallel_subagents_without_ids_keep_tool_results(self):
        """网关不给 tool_call id 时，并行子代理的工具结果不能被丢掉（否则下一轮请求 400）。"""
        first_call = {"index": 0, "id": "", "type": "function",
                      "function": {"name": "run_subagent",
                                   "arguments": json.dumps({"task": "写一句", "role": "写手A"},
                                                           ensure_ascii=False)}}
        second_call = {"index": 1, "id": "", "type": "function",
                       "function": {"name": "run_subagent",
                                    "arguments": json.dumps({"task": "写两字", "role": "写手B"},
                                                            ensure_ascii=False)}}
        two_calls = [
            {"choices": [{"delta": {"tool_calls": [first_call, second_call]}}]},
            {"choices": [{"delta": {}, "finish_reason": "tool_calls"}], "usage": usage()},
        ]

        def scripted(request):
            names = [spec["function"]["name"] for spec in request.get("tools") or []]
            if "run_subagent" in names:
                return two_calls if not self.upstream.requests or len(self.upstream.requests) == 1 \
                    else answer_round("两个子代理都回来了")
            return answer_round("子代理的回答")

        self.upstream.script = [scripted]
        settings = self.settings()
        store = core.SessionStore(self.data)
        session = store.create(title="并行子代理", model="")
        handler = tools_module.Tools(settings, self.data)
        client = core.client_for(settings.resolve_model())
        events = []
        runner = core.AgentRun(settings, session, client, handler, events.append,
                              lambda *args: True, threading.Event(), store=store)
        runner.subagent_runner = core.make_subagent_runner(
            settings, client, handler, events.append, threading.Event())
        runner.run("派两个子代理")

        assistant_with_calls = [message for message in session["messages"]
                                if message.get("tool_calls")]
        self.assertTrue(assistant_with_calls, "这一轮应该带工具调用")
        call_ids = [call["id"] for call in assistant_with_calls[0]["tool_calls"]]
        tool_ids = [message.get("tool_call_id") for message in session["messages"]
                    if message.get("role") == "tool"]
        self.assertTrue(all(call_id for call_id in call_ids), "缺失的 id 应该被补上")
        self.assertEqual(sorted(tool_ids), sorted(call_ids),
                         "每个 tool_calls 都必须有对应的 tool 结果，否则下一轮请求会被接口拒绝")

    def test_transport_error_does_not_offer_continue(self):
        """网络断了什么都没写出来：只报错，不给“继续生成”（没有回答可以继续）。"""
        session = post_json(self.port, "/api/session/new", {"title": "断网"})["session"]
        self.upstream.script = [length_round("写了一半就被截断"),
                                {"error": {"message": "网络错误：连接被重置"}, "__status__": 502}]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "写长文"})
        kinds = [event["t"] for event in events]
        self.assertIn("error", kinds)
        done = [event for event in events if event["t"] == "done"][-1]
        self.assertFalse(done["canContinue"])
        stored = get_json(self.port, "/api/session?id=" + session["id"])["session"]
        self.assertFalse(stored.get("incomplete"))

    def test_lan_mode_gets_a_token(self):
        """监听局域网时必须带令牌（否则同网段任何人都能执行本机命令）。"""
        source = os.path.join(HERE, "server.py")
        with open(source, "r", encoding="utf-8") as handle:
            code = handle.read()
        self.assertIn("secrets.token_urlsafe(16)", code)          # 没配令牌时自动生成
        self.assertIn('settings.save_webui({"access_token": token})', code)

        # 循环地址不需要令牌
        state = get_json(self.port, "/api/state")
        self.assertTrue(state["ok"])
        app = self.http.app
        app.settings.webui["access_token"] = "secret-token"
        try:
            # 真的绑到了局域网上（不是配置里写了什么，而是服务器实际绑了什么）：
            # 没令牌必须 401
            self.http.bind_host = "0.0.0.0"
            with self.assertRaises(urllib.error.HTTPError) as caught:
                get_json(self.port, "/api/state")
            self.assertEqual(caught.exception.code, 401)
            request = urllib.request.Request("http://127.0.0.1:%d/api/state" % self.port,
                                             headers={"X-Auth-Token": "secret-token"})
            with urllib.request.urlopen(request, timeout=20) as response:
                self.assertTrue(json.loads(response.read().decode("utf-8"))["ok"])
            # 令牌为空时不能因为 "" == "" 就放行
            app.settings.webui["access_token"] = ""
            with self.assertRaises(urllib.error.HTTPError) as caught:
                get_json(self.port, "/api/state")
            self.assertEqual(caught.exception.code, 401)
        finally:
            self.http.bind_host = "127.0.0.1"
            app.settings.webui["access_token"] = ""

    def test_auth_follows_the_real_bind_address_not_the_config_file(self):
        """`--host 0.0.0.0` 会覆盖配置文件里的 host。

        以前鉴权看的是配置（还是 127.0.0.1），于是服务监听在局域网上、
        界面上还打印了带令牌的地址，实际却谁都不用带令牌——同网段谁都能执行本机命令。
        """
        app = self.http.app
        self.assertEqual(app.settings.webui.get("host"), "127.0.0.1")
        self.http.bind_host = "0.0.0.0"
        app.settings.webui["access_token"] = "secret-token"
        try:
            with self.assertRaises(urllib.error.HTTPError) as caught:
                get_json(self.port, "/api/state")
            self.assertEqual(caught.exception.code, 401)
        finally:
            self.http.bind_host = "127.0.0.1"
            app.settings.webui["access_token"] = ""

    def test_cross_site_post_is_rejected(self):
        """别的网站不能借浏览器之手让本机执行命令（CSRF）。"""
        request = urllib.request.Request(
            "http://127.0.0.1:%d/api/command" % self.port,
            data=json.dumps({"command": "echo hi"}).encode("utf-8"),
            headers={"Content-Type": "application/json", "Origin": "http://evil.example"})
        with self.assertRaises(urllib.error.HTTPError) as caught:
            urllib.request.urlopen(request, timeout=20)
        self.assertEqual(caught.exception.code, 403)

    def test_port_already_serving_is_detected(self):
        """双击两次启动器时，第二次要能认出“已经在跑了”，而不是再起一个服务。"""
        self.assertTrue(server_module._already_running("127.0.0.1", self.port))
        self.assertFalse(server_module._already_running("127.0.0.1", 1))
        # Windows 上不能开 SO_REUSEADDR：否则第二个进程能绑同一个端口，两个服务各写一份会话
        self.assertFalse(server_module.QuietServer.allow_reuse_address if os.name == "nt" else False)

