    def test_chat_stream_tool_call_and_confirm_gate(self):
        target = os.path.join(self.workspace, "资料.txt")
        with open(target, "w", encoding="utf-8") as handle:
            handle.write("hello from file")
        self.upstream.script = [
            tool_round("read_file", json.dumps({"path": target})),
            answer_round("文件内容是 hello from file。"),
        ]
        session = post_json(self.port, "/api/session/new", {"title": "端到端"})["session"]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "读一下资料.txt"})
