    def test_confirm_gate_denies_high_risk_command(self):
        post_json(self.port, "/api/settings", {"settings": {"confirm_high_risk_commands": True}})
        self.upstream.script = [
            tool_round("run_command", json.dumps({"command": "powershell -Command exit"})),
            answer_round("已跳过。"),
        ]
        session = post_json(self.port, "/api/session/new", {"title": "确认门"})["session"]
        seen = {"confirm": None}
        holder = {}

        def on_event(event):
            if event["t"] == "start":
                holder["runId"] = event["runId"]
            if event["t"] == "confirm":
                seen["confirm"] = event
                post_json(self.port, "/api/confirm",
                          {"runId": holder["runId"], "id": event["id"], "approved": False})

        events = sse_chat(self.port, {"sessionId": session["id"], "text": "执行高风险命令"},
                          on_event=on_event)
        self.assertIsNotNone(seen["confirm"])
        self.assertIn("powershell", seen["confirm"]["args"]["command"])
        tool_end = [event for event in events if event["t"] == "tool_end"][0]
        self.assertEqual(tool_end["status"], "denied")

    def test_confirm_gate_works_when_switches_are_on(self):
        """确认框默认不弹；打开开关之后，鼠标/消息这类动作必须走完整的确认门。"""
        # 走接口改（服务端会重新读配置），跟老师在设置里勾选的效果一致
        post_json(self.port, "/api/settings", {"settings": {
            "confirm_desktop_input": True, "confirm_messages": True}})
        for name, args, hint in (
                ("click", {"loc": [300, 400]}, "模拟鼠标"),
                ("send_email", {"subject": "成绩", "body": "家长您好"}, "发送邮件"),
                ("send_qq_message", {"text": "下课了"}, "QQ")):
            # 模拟服务按"第几次请求"取剧本，所以每轮都要把计数清零
            self.upstream.requests = []
            self.upstream.script = [
                tool_round(name, json.dumps(args, ensure_ascii=False)),
                answer_round("已取消。"),
            ]
            session = post_json(self.port, "/api/session/new", {"title": name})["session"]
            seen = {}
            holder = {}

            def on_event(event, seen=seen, holder=holder):
                if event["t"] == "start":
                    holder["runId"] = event["runId"]
                if event["t"] == "confirm":
                    seen["confirm"] = event
                    post_json(self.port, "/api/confirm",
                              {"runId": holder["runId"], "id": event["id"], "approved": False})

            events = sse_chat(self.port, {"sessionId": session["id"], "text": "试一下"},
                              on_event=on_event)
            self.assertIn("confirm", seen, "%s 必须弹确认" % name)
            self.assertIn(hint, seen["confirm"]["reason"], "%s 的确认理由要说人话" % name)
            tool_end = [event for event in events if event["t"] == "tool_end"][0]
            self.assertEqual(tool_end["status"], "denied", "老师点了拒绝就不能执行")
            # 拒绝之后不能真的动鼠标/发消息（这里断言的是没有 tool_end 的 ok 状态）
            self.assertNotEqual(tool_end.get("status"), "ok")

    def test_screenshot_through_chat_needs_no_confirmation(self):
        """只读的截屏不该每次都弹框（否则老师会被烦死），但要真的返回可注入的图片。"""
        ok, message = desktop_module.available()
        if not ok:
            self.skipTest("桌面控制不可用：%s" % message)
