    def test_tool_pair_400_is_not_mistaken_for_missing_tool_support(self):
        """网关报"工具配对不对"时，不能误判成"模型不支持工具"并把工具关掉。"""
        session = post_json(self.port, "/api/session/new", {"title": "配对被拒"})["session"]
        self.upstream.requests = []
        self.upstream.script = [
            {"__status__": 400, "error": {"message":
                "An assistant message with 'tool_calls' must be followed by tool messages "
                "responding to each 'tool_call_id'. (insufficient tool messages following "
                "tool_calls message)"}},
            answer_round("好的。"),
        ]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "你好"})
        notices = [event["message"] for event in events if event["t"] == "notice"]
        self.assertTrue(any("配对不完整" in item for item in notices), notices)
        self.assertFalse(any("不支持工具调用" in item for item in notices),
                         "这不是「模型不支持工具」，不能这么报")
        self.assertGreaterEqual(len(self.upstream.requests), 2, "应该重试一次")
        self.assertIn("tools", self.upstream.requests[1], "重试时不能把工具关掉")

    def test_mouse_and_message_tools_run_without_a_confirm_dialog(self):
        """默认设置下：动手类与消息类工具都直接执行，不弹确认框。

        这里挑的是"没配置就立刻报错、不会真动手"的几个（发邮件/推群/切一个不存在的窗口），
        所以既能证明它们真的被执行了，又不会在测试机上留下副作用。
        """
        self.upstream.requests = []
        self.upstream.script = [
            two_tool_round([("call_mail", "send_email",
                             json.dumps({"subject": "测试", "body": "正文"}, ensure_ascii=False)),
                            ("call_hook", "notify_webhook",
                             json.dumps({"text": "下课"}, ensure_ascii=False)),
                            ("call_win", "app",
                             json.dumps({"mode": "info", "name": "绝对不存在的窗口xyz"},
                                        ensure_ascii=False))]),
            answer_round("好的。"),
        ]
        session = post_json(self.port, "/api/session/new", {"title": "免确认"})["session"]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "试一下"})
        self.assertNotIn("confirm", [event["t"] for event in events],
                         "默认不该弹任何确认框")
        ends = {event["name"]: event for event in events if event["t"] == "tool_end"}
        self.assertEqual(sorted(ends), ["app", "notify_webhook", "send_email"])
        for name, event in ends.items():
            self.assertNotEqual(event["status"], "denied", "%s 不该被拒绝" % name)
            # 有输出就说明工具真的跑起来了（没配置会报"还没配置"，那是执行后的结果）
            self.assertTrue(event.get("output"), "%s 应该有执行结果" % name)
        self.assertIn("还没配置", ends["send_email"]["output"])
        self.assertIn("还没配置", ends["notify_webhook"]["output"])

    def test_two_tools_with_image_injection_keep_pairs_contiguous(self):
        """一轮两个工具、其中一个注入图片：历史里图片必须排在**所有**工具结果之后。

        线上那句 400 就是这么来的：图片被插在两条工具结果中间，
        assistant(tool_calls=[A,B]) → tool(A) → user(图片) → tool(B)。
        """
        image = os.path.join(self.workspace, "看图.png")
        with open(image, "wb") as handle:
            handle.write(tiny_png(8, 8))
        self.upstream.requests = []
        self.upstream.script = [
            two_tool_round([("call_img", "view_image", json.dumps({"path": image})),
                            ("call_dir", "list_dir", json.dumps({"path": self.workspace}))]),
            answer_round("我看到了一张图。"),
        ]
        session = post_json(self.port, "/api/session/new", {"title": "双工具"})["session"]
        events = sse_chat(self.port, {"sessionId": session["id"], "text": "看图并列出目录"})
        self.assertNotIn("error", [event["t"] for event in events])

        stored = get_json(self.port, "/api/session?id=" + session["id"])["session"]
        roles = [message["role"] for message in stored["messages"]]
        self.assertEqual(roles[:4], ["user", "assistant", "tool", "tool"],
                         "两条工具结果必须紧跟 assistant(tool_calls)，实际 %s" % roles)
        self.assertEqual(roles[4], "user", "注入的图片消息要排到工具结果之后")
        self.assertTrue(stored["messages"][4].get("injected"))

        # 真正发出去的请求也必须合法
        sent = self.upstream.requests[0]["messages"]
        assert_valid_tool_pairs(self, sent)

    def test_broken_legacy_session_is_repaired_before_sending(self):
        """旧版本存下来的坏会话：直接发会 400，现在要先整理再发。"""
        session = post_json(self.port, "/api/session/new", {"title": "旧会话"})["session"]
