    def test_resources_are_consistent(self):
        """交叉检查前端引用：id、图标、接口路径、启动器提到的文件都要真实存在。

        （这类"引用了不存在的东西"不会报错，只会静默变成空白或 404，所以必须查。）
        """
        ui = os.path.join(HERE, "ui")
        html = self.files["index.html"]
        ids_in_html = set(re.findall(r'id="([A-Za-z0-9_-]+)"', html))
        referenced = set(re.findall(r"\$\('#([A-Za-z0-9_-]+)'\)", self.all_js))
        referenced |= set(re.findall(r"getElementById\('([A-Za-z0-9_-]+)'\)", self.all_js))
        self.assertEqual(sorted(referenced - ids_in_html), [],
                         "JS 引用了 index.html 里不存在的 id")

        icons = set(re.findall(r"^\s*([a-zA-Z][A-Za-z0-9]*):\s*'", self.files["icons.js"], re.M))
        used = set(re.findall(r'data-icon="([A-Za-z0-9]+)"', html))
        used |= set(re.findall(r"data-icon=\\?\"([A-Za-z0-9]+)\\?\"", self.all_js))
        used |= set(re.findall(r"icon\('([A-Za-z0-9]+)'", self.all_js))
        used |= set(re.findall(r"iconButton\([^)]*?'([a-zA-Z][A-Za-z0-9]*)'", self.all_js))
        used |= set(re.findall(r"svgIcon\('([A-Za-z0-9]+)'", self.all_js))
        missing = sorted(name for name in used - icons if name not in ("di", "span", "button"))
        self.assertEqual(missing, [], "用到但 icons.js 里没有的图标（会显示成空白）")
        self.assertNotIn("alert:", self.files["icons.js"], "没人用的图标应当删掉")

        with open(os.path.join(HERE, "server.py"), "r", encoding="utf-8") as handle:
            server_source = handle.read()
        registered = set(re.findall(r'path == "(/api/[a-z_/]+)"', server_source))
        called = set(re.findall(r"'(/api/[a-z_/]+)", self.all_js))
        self.assertEqual(sorted(called - registered), [], "前端调用了服务端没有的接口")

        # JS 里的类名基本都有样式（漏了不会报错，只会显示得很怪）。
        # 两份样式表都要看：空间右栏和平面「代数区」共用 .plane-row / .plane-empty
        # 那一套（定义在 plane.css 里），只看 style.css 会误报。
        css = self.files["style.css"] + "\n" + self.files["plane.css"]
        used_classes = set()
        for match in re.findall(r"el\('[a-z]+',\s*'([^']+)'", self.all_js):
            used_classes.update(match.split())
        for name in sorted(used_classes):
            if name in ("hidden", "hidden-input") or name in css:
                continue
            self.assertIn("." + name, css, "JS 用到但 CSS 里没有的类名：%s" % name)

        # 启动器会用到的文件必须随包存在（少了会在老师机器上直接失败）
        launcher = os.path.join(HERE, os.pardir, "start-webui.cmd")
        with open(launcher, "r", encoding="utf-8") as handle:
            launcher_text = handle.read()
        root = os.path.abspath(os.path.join(HERE, os.pardir))
        for name in ("agent.ico", os.path.join("webui", "server.py"),
                     os.path.join("config", "agent.example.json")):
            self.assertIn(name.replace("\\", os.sep).split(os.sep)[-1], launcher_text.replace("\\", os.sep))
            self.assertTrue(os.path.exists(os.path.join(root, name)),
                            "启动器/文档提到但包里没有的资源：%s" % name)
        with open(os.path.join(root, "config", "agent.example.json"), "r", encoding="utf-8") as handle:
            example = json.load(handle)
        self.assertEqual(example["api_key"], "", "示例配置不能带任何密钥")
        self.assertIn("deepseek", example["base_url"])
        self.assertNotIn("sk-", json.dumps(example))

        # 技能目录里每个技能都要有 SKILL.md，否则界面上会出现点不开的空技能
        skills_root = os.path.join(HERE, os.pardir, "skills")
        if os.path.isdir(skills_root):
            folders = [name for name in os.listdir(skills_root)
                       if os.path.isdir(os.path.join(skills_root, name))]
            self.assertTrue(folders, "skills 目录是空的")
            missing_skill = [name for name in folders
                             if not os.path.isfile(os.path.join(skills_root, name, "SKILL.md"))]
            self.assertEqual(missing_skill, [], "这些技能目录里没有 SKILL.md")

    def test_screenshots_stay_out_of_the_artifact_strip(self):
        """「本次产物」只摆老师要拿走的东西，不摆 AI 自己看的截图。

        老师反馈"产物不要显示截图之类的了，不然太冗杂了"：截一次屏就多一个缩略图，
        产物栏很快变成一堵墙。截图/界面快照/看图/发 QQ 的确认截图都不该进来，
        而课件、下载的文件、引用过的文件照旧要露出来。
        """
        js = self.files["app.js"]
        self.assertIn("ARTIFACT_SKIP_TOOLS", js)
        for tool in ("screenshot", "snapshot", "view_image", "send_qq_message", "app"):
            self.assertIn(tool + ": 1", js, "%s 的截图不该进产物栏" % tool)
        body = js[js.index("function toolArtifacts"):]
        body = body[:body.index("function artifactAction")]
        self.assertIn("ARTIFACT_SKIP_TOOLS[name]", body, "先按工具名过滤")
        self.assertNotIn("screenshot", body, "screenshot 那条产物分支要删掉")
        self.assertNotIn("view_image", body, "视图图片那条分支要删掉")
        self.assertIn("name === 'write_file'", body, "真正做出来的文件照旧要显示")

