    def test_stream_timeline_structure(self):
        """思考、正文、工具调用按发生顺序排在一条时间线上。

        这是老师点名要的（对照 DSH 的观感）：以前所有思考都堆在最上面那个折叠栏里、
        正文在最下面一直长，结果"完成一轮思考、说了话之后再思考"看不到新的一行，
        内容一长也看不到最新的思考和工具调用。现在每一段思考、每一段正文各自成节点，
        依次往下排——最新的一定在最下面。
        """
        css = self.files["style.css"]
        for anchor in (".stream {", ".stream > .content { margin: 0; }",
                       ".step.think", ".step.think.live", "keyframes spin"):
            self.assertIn(anchor, css)
        for anchor in ("function streamNode()", "function streamAppend(", "function streamThink(",
                       "function streamText(", "function streamBreak(", "ctx.stream.appendChild",
                       "thinkStep", "thinkTrim", "thinkAppend", "streamThink(ctx, '')",
                       "streamText(ctx, '')"):
            self.assertIn(anchor, self.js)
        # 旧的"一个折叠栏装下所有步骤"的结构必须已经清干净，否则两种渲染会打架
        for gone in ("buildFold", "foldAddStep", "foldFinish", "foldStatus", "ctx.fold",
                     "W7Fold", "fold-body", ".fold {"):
            self.assertNotIn(gone, self.js + css, "旧折叠栏结构还留着：%s" % gone)
        # 一轮结束时"收尾"：后面再有思考/正文才可能另起节点
        turn = self.js.split("function onTurn(event) {", 1)[1].split("\n  }", 1)[0]
        self.assertIn("streamBreak(ctx)", turn)
        self.assertNotIn("ctx.raw.content = ''", turn)
        # 新的一轮（round 事件）也要切开，否则连续两轮的思考会粘在一起
        round_block = self.js.split("function onRound(event) {", 1)[1].split("\n  }", 1)[0]
        self.assertIn("streamBreak(ctx)", round_block)
        # 历史渲染走同一条时间线（刷新后结构一致），而不是把正文拼成一条流水账
        history = self.js.split("function assistantTurnNode(", 1)[1].split("\n  }", 1)[0]
        for anchor in ("streamThink(historyCtx", "streamText(historyCtx", "streamNode()"):
            self.assertIn(anchor, history)
        self.assertNotIn(".map(function (message) { return message.content || ''; })", self.js)
        self.assertIn("turns.push({ user: message, parts: [] })", self.js)
        # 正文太长时，最新的那条要能被滚进视野
        self.assertIn("function keepLatestInView(", self.js)
        self.assertIn("keepLatestInView(ctx)", self.js)

