    def test_canvas_writes_a_real_png(self):
        canvas = winimage_module.Canvas(4, 3, b"\x20\x30\x40\xff" * 12)
        canvas.draw_rect((0, 0, 2, 2), color=(255, 0, 0))
        head = canvas.png_bytes()
        self.assertEqual(head[:8], b"\x89PNG\r\n\x1a\n", "必须是真正的 PNG 字节流")
        self.assertIn(b"IHDR", head)
        self.assertIn(b"IEND", head)
        path = os.path.join(self.workspace, "画布.png")
        canvas.save_png(path)
        with open(path, "rb") as handle:
            self.assertEqual(handle.read(8), b"\x89PNG\r\n\x1a\n")
        self.assertGreater(os.path.getsize(path), 40)

