    def test_canvas_measures_its_container_before_drawing(self):
        """画布必须按容器实测像素写 width/height：只靠 viewBox 的话 SVG 会按 2:1 自己算高度，
        画布一变矮（下面多了图像区）就把下半截裁掉，板、轨道、地面全看不见（老师反馈过）。"""
        self.assertIn("function sizeCanvas()", self.sandbox)
        applied = self.sandbox[self.sandbox.index("function applyView() {"):]
        head = applied[:applied.index("svg.setAttribute('viewBox'")]
        self.assertIn("sizeCanvas();", head, "applyView 要先量容器，再写 viewBox")
        self.assertIn("$('#sandboxPanel .sandbox-canvas')", self.sandbox,
                      "量画布容器要限定在物理沙盒面板里，别量到别的画布")
        self.assertNotIn("document.querySelector('.sandbox-canvas')", self.sandbox,
                         "全局找 .sandbox-canvas 会量错面板")

