        self.assertTrue(self.call("plane", {"action": "set_style", "id": "f1",
                                            "style": {"color": "#e5484d"}})[0]["ok"])

        self.assertTrue(self.call("plane", {"action": "zoom", "factor": 2})[0]["ok"])
        wide = self.call("plane", {"action": "export"})[0]["state"]["view"]
