def extract_js_function(path, name):
    """从任意 ui\\*.js 里抠出一个**真函数**（按大括号配对）。同 extract_plane_function。"""
    with open(path, "r", encoding="utf-8") as handle:
        text = handle.read()
    start = text.index("  function %s(" % name)
    body = text[start:]
    depth = 0
    for index, char in enumerate(body):
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return body[:index + 1]
    raise AssertionError("%s 的大括号没配平（%s 被改坏了？）" % (name, path))


def extract_plane_function(name):
    """从 ui\\plane.js 里抠出一个**真函数**（按大括号配对）交给 node 跑断言。

    抄一份等价的 Python 测的是副本，改了 plane.js 也发现不了（TestSnapDetent 同理）。
    """
    return extract_js_function(os.path.join(HERE, "ui", "plane.js"), name)


class TestPlaneReplacesOldFigure(WebUITestCase):
    """「平面模块替换旧的函数 / 方程 / 平面几何」这条迁移的守门测试。

    老师原话："把平面模块用来替换以前的函数、方程、平面几何模块"——是**替换**，
    不是并存。所以这里同时钉三件事：
      1. /api/figure 只认 kind=solid，其余结构化拒绝并指名平面（和 AI 侧对齐）；
      2. 旧面板的类型标签（函数 / 方程 / 几何图形）从 index.html 里**消失**了；
      3. 几何画板（平面面板）的工具行和方程输入栏**还在**——被删的只能是旧的。
    """

    def setUp(self):
        WebUITestCase.setUp(self)
        self.port = self.start_http()          # 要真发一次 POST 才验得了"结构化拒绝"

    def test_solid_sidebar_is_redrawn_from_scratch(self):
        """空间右栏每次重画都要从空开始。

        老师反馈"清空之后右栏还留着一大堆不存在的点、线、面、角、体"：
        renderSolidInfo 只往 #figureInfo 里 append，拖动中每 70ms 重画一次就多糊一层，
        按「清空」只清掉了对象、清不掉那一摞卡片。所以这里钉住"先清空再画"。
        """
        app = self.app()
        self.assertIn("function renderSolidInfo", app)
        head = app[app.index("function renderSolidInfo"):]
        head = head[:head.index("box.appendChild(head)")]
        self.assertIn("box.innerHTML = ''", head,
                      "右栏要先清空再画，不然每次重画都会叠一层，清空也清不掉")
        # 角要置顶：老师点「线线角 / 线面角 / 面面角」就是为了看这个数，
        # 排在点/棱/面/圆/球下面得往下翻（老师反馈"很不方便"）。
        body = app[app.index("function renderSolidInfo"):]
        body = body[:body.index("function infoRow")]
        self.assertLess(body.index("var angles = figure.angles"),
                        body.index("points.forEach(function (item) {"),
                        "角那张卡片要排在对象列表前面（置顶）")

    def test_solid_picking_survives_a_previous_drag(self):
        """上一次拖动的计数不许把后面的点击吃掉，动点的约束不许拖走别的点。

        两条都是真机反馈换来的：
          1) "选面面角等工具都无法通过点击屏幕选择点了" —— dragMoved 是上一次拖动累积
             下来的数、谁都没清过，solidPickAt 却拿它单独判断，于是拖过一回之后
             点哪儿都不选（现在只在"这一下真的在拖"时才看它，而且每次按下归零）；
          2) "拖动圆上动点时，如果和圆上定点重合，会把定点无限制地拖走、圆不断变化" ——
             动点的约束是**属于某一个点**的，按在别的点上不能拿它起拖。
        """
        app = self.app()
        self.assertIn("var wasDragging = solidState.dragging;", app,
                      "dragMoved 必须只在'这一下真在拖'时才参与判断")
        self.assertIn("solidState.dragMoved = 0;", app, "每次按下要重新开始记动了多少")
        self.assertIn("if (point.name !== (constraint.point || constraint.name)) return false;",
                      app, "动点的约束不能拿来拖别的点（会把定点拖走、圆跟着变）")

    def test_window_route_carries_the_vertical_range(self):
        """网页端把可见范围报上来：/api/plane/window 收 x，也收 y。

        老师反馈「AI 不会画无限函数和方程」：函数早就跟着视野走了，方程（隐式）
        吃的是二维采样框，只有把 y 一起报上来它才会跟着视野重采样。
        顺便钉住"只报 x 也得能用"：老页面只报 x，不该报错、也不该动采样框。
        """
        plane_hub_module.reset()
        handler = self.make_tools()
        payload = json.loads(handler.run("plane", {"action": "plot_implicit",
                                                   "expr": "y-x^2", "id": "par"})[0])
        self.assertTrue(payload["ok"], payload)
        before = get_json(self.port, "/api/plane/state")["state"]["objects"]["par"]["value"]["bbox"]
        self.assertLess(before[3], 20, "默认视图里这条方程本来就只画一小截")
        only_x = post_json(self.port, "/api/plane/window", {"xmin": -10, "xmax": 10})
        self.assertTrue(only_x["ok"], only_x)
        self.assertEqual(get_json(self.port, "/api/plane/state")["state"]["objects"]["par"]["value"]["bbox"],
                         before, "只报 x 不许动隐式曲线的采样框（把框拉大线会变稀）")
        both = post_json(self.port, "/api/plane/window",
                         {"xmin": -10, "xmax": 10, "ymin": 95, "ymax": 105})
        self.assertTrue(both["ok"], both)
        after = get_json(self.port, "/api/plane/state")["state"]["objects"]["par"]["value"]["bbox"]
        self.assertGreater(after[1], 20, "报了可见范围之后方程要画到 y=100 附近")
        # 版本号不能被"报视野"推着走：拖一下视野不该变成一次可撤销的操作
        self.assertEqual(only_x["stateVersion"], both["stateVersion"], "同步视野不许加版本号")
        bad = post_json(self.port, "/api/plane/window",
                        {"xmin": -10, "xmax": 10, "ymin": 5, "ymax": -5})
        self.assertFalse(bad.get("ok", True), "ymin > ymax 要当场报错")
        self.assertIn("ymin", json.dumps(bad, ensure_ascii=False))

    def html(self):
        with open(os.path.join(HERE, "ui", "index.html"), encoding="utf-8") as handle:
            return handle.read()

    def app(self):
        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            return handle.read()

    def test_figure_endpoint_refuses_every_non_solid_kind(self):
        """函数 / 方程 / 几何一律拒绝，错误里点名平面接口。"""
        for body in ({"kind": "function", "expression": "sin(x)"},
                     {"kind": "equation", "expression": "x^2 + y^2 = 4"},
                     {"kind": "geometry", "shapes": ["A(0,0)", "circle A 2"]}):
            with self.assertRaises(urllib.error.HTTPError) as ctx:
                post_json(self.port, "/api/figure", body)
            self.assertEqual(ctx.exception.code, 400, body)
            payload = json.loads(ctx.exception.read().decode("utf-8"))
            error = payload["errors"][0]
            self.assertEqual(error["code"], "wrong_tool", body)
            self.assertIn("/api/plane/apply", error["hint"],
                          "指路要写到具体路由，光说“用平面”模型和老师都接不上")
            self.assertIn("plane", error["hint"], body)
        # solid 仍然可用（立体不归平面管）
        figure = post_json(self.port, "/api/figure", {
            "kind": "solid", "shapes": ["A(0,0,0)", "B(1,0,0)", "C(0,1,0)", "face A B C"]})["figure"]
        self.assertEqual(figure["kind"], "solid")
        self.assertTrue(figure["faces"])

