    def test_slide_tool_and_edge_drag_stay_wired(self):
        """「沿线拖」三种模式 + 空间拖整条棱：要保的是**指定的那个不变量**。

        老师先要"沿线拖动线段、曲线上的定长弦"，随后指出："你只是保证了线段的 x 方向长度
        不变而不是线段长度不变，要拆成 3 个功能"（保 x / 保长度 / 保 y）。
        所以这里把三件事一起钉住：
          · 三个工具名各自对应一个不变量（SLIDE_MODES）；
          · 曲线轨道上另一端是**解**出来的（cacheSolve），不是同加一个 Δ 参数；
          · 直线类轨道是刚体平移（三个不变量同时成立），走精确那条路；
          · 两个端点同一批发（一批才不会画出被拉歪的线段）。
        """
        with open(os.path.join(HERE, "ui", "plane.js"), encoding="utf-8") as handle:
            plane = handle.read()
        for needle in ("function armSlide", "function slideTargets",
                       "function slideOpsFor", "function startSlide", "function slideTo",
                       "function cacheSolve", "function hostPointAt"):
            self.assertIn(needle, plane, "平面沿线拖缺 %s" % needle)
        # 三个工具 -> 三个不变量
        self.assertIn("var SLIDE_MODES = { slide: 'length', slidex: 'x', slidey: 'y' };", plane)
        # 曲线轨道走求解；直线类走刚体平移
        self.assertIn("follower = cacheSolve(cache, drag.mode, leader, value, drag.base[1],",
                      plane)
        self.assertIn("crossUnbounded(objById(def.intersect[0]), objById(def.intersect[1]));",
                      plane)
        # 取参：投影到折线上（连续、不吸附格子），直线整条扫、曲线只扫上一帧附近
        self.assertIn("cacheProject(cache, point, typeof drag.where === 'number' ? drag.where : 0,",
                      plane)
        self.assertIn("drag.straight ? 1 : 0.12, drag.wrap);", plane)
        # 抖动要在**输入**这头挡住（手指没挪够 3 像素就整帧不做），不是把解糊掉
        self.assertIn("drag.anchor = { x: point.x, y: point.y };", plane)
        # 端点一动，挂在它身上的切线 / 垂线也要跟着（否则"切线跟端点严重错位"）
        self.assertIn("previewDependents(ids, spots);", plane)
        self.assertIn("var LINE_TYPES = { perpendicular: 1, parallel: 1, perpendicular_bisector: 1,",
                      plane)
        self.assertIn("var STRAIGHT_HOSTS = { segment: 1, ray: 1, line: 1, vector: 1 };", plane)
        # 漏掉 pointerup / 切窗口都要收尾，不然"没按着也一直跟着鼠标走"
        self.assertIn("return !!(state.drag || state.pan || (state.slide && state.slide.drag));",
                      plane)
        self.assertIn("if (state.slide) state.slide.drag = null;", plane)
        # 按画布空白处 = 取消这次沿线拖（老师要的"点一下屏幕就复位"）
        self.assertIn("function endSlide", plane)
        self.assertIn("if (drag.straight) {", plane)
        # 直线类轨道是精确平移：本地预览和发出去的参数用的是同一份结果
        self.assertIn("var spots = slideTargets(state.slide.host, drag.base,", plane)
        # 线段轨道时 Δ 要整体收边（各自夹会把线段挤短）
        self.assertIn("delta = clamp(delta, -low, 1 - high);", plane)
        # 圆上要绕回去
        self.assertIn("value = value % 1;", plane)
        # 两个端点同一批发（rotateTo 的老规矩）
        self.assertIn("queueOp(slideOpsFor(", plane)
        # 函数轨道的取点要夹住目标（"最近点 + 邻居"会差半格，拖动时误差累积）
        self.assertIn("夹住", plane)

        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        for needle in ("function solidEdgeShift", "function solidEdgeUnder",
                       "function solidBeginEdgeDrag", "function solidAxisOf"):
            self.assertIn(needle, app, "空间拖棱缺 %s" % needle)
        self.assertIn("拖的是**整条棱**", app)
        self.assertIn("solidState.dragEdge", app)
        # 空间里"拖整条棱"必须和「沿线拖点」**分开**（老师要求"沿线拖只能拖点"）。
        # 拖棱的流程也是老师定的：**先点两个点（定轨道方向）+ 再点两个点（定要滑的线段）**，
        # 不用去点棱（棱的命中范围只有 14 像素、点有 30 像素，点棱根本点不准）。
        self.assertIn("edgealong: { label: '拖棱', steps: [2, 2]", app)
        self.assertIn("solidAlongLine: armedKind === 'alignline',", app)
        self.assertIn("solidState.edgeMode = (kind === 'edgealong');", app)
        self.assertIn("solidState.edgeMode = true;", app)
        self.assertIn("solidState.slidePair = armed.groups[1].slice();", app)
        # 这两行是"拖不了棱"的真正原因：拖整条棱时 dragPoint 是空的，
        # 原来那句无条件的 `if (!moving) return;` 让棱的拖动一帧都走不到。
        self.assertIn("var edgeDrag = !!(solidState.dragEdge && solidState.dragEdge.length === 2);",
                      app)
        self.assertIn("if (!moving && !edgeDrag) return;", app)
        # 每一步只要两个点的工具点够两个就自动进下一步 / 直接定下来（不用再按「确定」）
        self.assertIn("var autoNeed = autoSpec.steps[solidState.armed.stage];", app)
        self.assertIn("if (autoNeed <= 2 && solidState.selected.length === autoNeed) {", app)
        self.assertIn("edgeHinted", app)
        self.assertIn("想整条棱沿线滑", app)
        # 多点工具（连线 / 画面 / 画圆 / 画球 / 三种角）正在选点时，按点不能变成拖点：
        # 老师报的"没法点两个点创建棱，只连线还是当点拖动"就是这个（mousedown 无条件拖）。
        self.assertIn("if (solidState.armed) return;", app)
        self.assertIn("按在点上是在**选点**，不是拖它", app)
        with open(os.path.join(HERE, "ui", "index.html"), encoding="utf-8") as handle:
            html = handle.read()
        self.assertIn('id="solidAlongEdge"', html)
        self.assertIn("再点要滑的那条线段的两个端点", html)

    def test_slide_drag_is_cheap_enough_to_be_smooth(self):
        """拖动要丝滑：轨道采样只做一次、每帧只在缓存上走小步，而且本地先动。

        老师反馈"拖动起来仍然非常不丝滑"。根因是每帧都去把整条曲线重扫 360 遍
        （一帧几十万次运算），外加干等服务端那一趟才动。现在：
          · `hostCache` 在**按下时**把轨道缓存成参数均匀的折线（一次）；
          · `cachePointAt` 取点是 O(1)，`cacheProject` 只在缓存上扫一小段（约几十个点）；
          · `cacheSolve` 从**上一帧的解**出发走小步（GeoGebra 的路径拖动器就是这么做的）；
          · `optimisticMove` 先在本地把端点挪过去重画，线段立刻跟手；
          · `previewSlide` 把这次预览记进 `drag.spots`，`reapplyPreview` 在权威状态画完之后
            再贴一遍——不然服务端回来的旧值会把线段拉回头（老师说的"一直来回抽出"）。
        实测：200 帧从 559ms 降到 2ms（约 280 倍）——量在临时脚本里跑过，这里钉住结构。
        """
        with open(os.path.join(HERE, "ui", "plane.js"), encoding="utf-8") as handle:
            plane = handle.read()
        for needle in ("function hostCache", "function cachePointAt", "function useParameter",
                       "function cacheProject", "function cacheSolve", "function hostRange",
                       "function previewSlide", "function optimisticMove",
                       "function previewDependents", "function tangentDirection",
                       "function crossUnbounded", "function reapplyPreview",
                       "function refreshForDrag", "function drawPreviewSoon"):
            self.assertIn(needle, plane, "拖动缓存路径缺 %s" % needle)
        self.assertNotIn("function solveFollower", plane,
                         "每帧重扫整条曲线的老解法要删掉，别留着又被调回去")
        self.assertIn("cache: hostCache(host)", plane, "按下时缓存轨道（只做一次）")
        self.assertIn("drag.base[1] = follower;", plane, "每帧记下解，下一帧从它出发")
        # 直线轨道也要本地先动（以前只有曲线那条路预览，直线上还是干等服务端）
        self.assertIn("previewSlide(drag, spots);", plane)
        self.assertIn("previewSlide(drag, [leader, follower]);", plane)
        # 权威状态画完之后要把预览贴回去，否则线段被上一趟往返拉回头（"一直来回抽"）
        self.assertIn("drag.spots = spots;", plane)
        self.assertIn("if (!reapplyPreview()) drawGeometry();", plane)
        # 提交要节流：响应一回来就补发下一条 = 每秒几百次提交，主线程被占满（"一卡一卡"）
        self.assertIn("var OP_GAP_MS = 40;", plane)
        self.assertIn("state.opSentAt = Date.now();", plane)
        self.assertIn("pumpOps();", plane)
        self.assertIn("var wait = OP_GAP_MS - (Date.now() - (state.opSentAt || 0));", plane)
        # 死区只能是 1 像素：调大了就是"3 像素一跳"
        self.assertIn("var dead = state.unit || 0.03;", plane)
        # 拖动中不回读整份状态（和预览抢主线程）
        self.assertIn("if (state.opened) refreshForDrag();", plane)
        # 拖动中整份对齐限流：一次对齐十几毫秒主线程阻塞，每个 commit 都来就是"一卡一卡"
        self.assertIn("var DRAG_RENDER_MS = 250;", plane)
        self.assertIn("refreshForDrag();", plane)
        self.assertIn("if (owed) loadPlane();", plane)
        # 预览重画合并到动画帧（触屏一秒一百多个 pointermove，别每个都整图重建）
        self.assertIn("if (optimisticMove(drag.ids, spots)) drawPreviewSoon();", plane)
        # 拖动期间右栏 / 信息区一律不刷新：它们一改高度就把画布挤得变尺寸，
        # 画布一改尺寸，预览的位置相对手指就会来回偏（"跟不上 / 超前 + 窗口抖"）
        self.assertIn("if (!chromeFrozen()) refreshChrome();", plane)
        self.assertIn("return !!(state.slide && state.slide.drag);", plane)
        self.assertIn("refreshChrome();", plane)
        # 轨道尽头要提醒（不然就是"拖到一定距离就拖不动了"）
        self.assertIn("function hintSlideEdge", plane)
        # 服务端和解：更旧的权威状态不许覆盖已经预测出来的画（Gambetta 那篇的规矩）
        self.assertIn("if (isStaleRender(plane)) return;", plane)
        self.assertIn("state.renderedVersion = plane.version;", plane)
        # 视野同步 = 自动区间的曲线重采了：轨道缓存和参数都要重标
        self.assertIn("reseedSlideCache();", plane)

        with open(os.path.join(HERE, "ui", "app.js"), encoding="utf-8") as handle:
            app = handle.read()
        self.assertIn("乐观更新：先把本地这张图上的端点挪过去重画一遍", app,
                      "空间拖棱也要先本地动，别干等服务端")

    def test_dragging_a_segment_picks_by_midpoint(self):
        """拖线段/棱的"就近原则"：**中点离鼠标最近**的那条（老师定的）。

        理由是两条线段挨在一起、或者按在共用端点附近时，"点到线段的垂距"几乎一样大，
        挑中的常常不是老师想拖的那条；中点最近的那条才是他心里那条。
        """
